"""Motor offline-first de automoderação e tickets do Pimcord.

O motor decide e registra localmente; a aplicação escolhe como executar a ação
no Discord. Isso mantém testes determinísticos e evita punições acidentais sem
permissões explícitas.
"""
from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import StrEnum
from typing import Any, Iterable


class AcaoModeracao(StrEnum):
    AVISAR = "avisar"
    APAGAR = "apagar"
    SILENCIAR = "silenciar"
    EXPULSAR = "expulsar"
    BANIR = "banir"
    BLOQUEAR = "bloquear"


@dataclass(slots=True, frozen=True)
class RegraModeracao:
    """Regra local; padrões são comparados após normalização de texto."""

    nome: str
    padroes: tuple[str, ...]
    acao: AcaoModeracao = AcaoModeracao.AVISAR
    motivo: str = "Violação de regra de automoderação"
    habilitada: bool = True
    regex: bool = False
    abrir_ticket: bool = True

    def __post_init__(self) -> None:
        if not self.nome.strip():
            raise ValueError("nome da regra não pode ser vazio")
        if not self.padroes:
            raise ValueError("a regra precisa de pelo menos um padrão")
        if any(not str(padrao).strip() for padrao in self.padroes):
            raise ValueError("padrões vazios não são permitidos")


@dataclass(slots=True, frozen=True)
class DecisaoModeracao:
    detectada: bool
    regra: str | None = None
    acao: AcaoModeracao | None = None
    motivo: str | None = None
    correspondencia: str | None = None


@dataclass(slots=True, frozen=True)
class RegistroModeracao:
    criado_em: datetime
    servidor_id: str | None
    canal_id: str | None
    mensagem_id: str | None
    usuario_id: str | None
    decisao: DecisaoModeracao


@dataclass(slots=True)
class TicketModeracao:
    id: int
    registro: RegistroModeracao
    status: str = "aberto"
    observacoes: list[str] = field(default_factory=list)

    def fechar(self, observacao: str | None = None) -> None:
        self.status = "fechado"
        if observacao:
            self.observacoes.append(observacao)


def normalizar_texto(texto: str) -> str:
    """Remove variações Unicode e espaços para reduzir evasões triviais."""
    texto = unicodedata.normalize("NFKC", str(texto)).casefold()
    texto = "".join(
        caractere for caractere in unicodedata.normalize("NFKD", texto)
        if not unicodedata.combining(caractere)
    )
    return re.sub(r"\s+", " ", texto).strip()


class MotorAutomoderacao:
    """Avalia mensagens sem rede e conserva evidências de cada decisão."""

    def __init__(self, regras: Iterable[RegraModeracao] | None = None) -> None:
        self.regras: dict[str, RegraModeracao] = {}
        self.registros: list[RegistroModeracao] = []
        self.tickets: dict[int, TicketModeracao] = {}
        self._proximo_ticket = 1
        for regra in regras or ():
            self.adicionar_regra(regra)

    def adicionar_regra(self, regra: RegraModeracao) -> RegraModeracao:
        if regra.nome in self.regras:
            raise ValueError(f"regra já cadastrada: {regra.nome}")
        self.regras[regra.nome] = regra
        return regra

    def remover_regra(self, nome: str) -> RegraModeracao | None:
        return self.regras.pop(nome, None)

    def avaliar(self, conteudo: str, *, servidor_id: str | None = None, canal_id: str | None = None, mensagem_id: str | None = None, usuario_id: str | None = None) -> DecisaoModeracao:
        texto = normalizar_texto(conteudo)
        for regra in self.regras.values():
            if not regra.habilitada:
                continue
            for bruto in regra.padroes:
                padrao = normalizar_texto(bruto)
                encontrou = re.search(padrao, texto) if regra.regex else (padrao in texto)
                if encontrou:
                    decisao = DecisaoModeracao(True, regra.nome, regra.acao, regra.motivo, encontrou.group(0) if hasattr(encontrou, "group") else padrao)
                    registro = RegistroModeracao(datetime.now(timezone.utc), servidor_id, canal_id, mensagem_id, usuario_id, decisao)
                    self.registros.append(registro)
                    if regra.abrir_ticket:
                        ticket = TicketModeracao(self._proximo_ticket, registro)
                        self.tickets[ticket.id] = ticket
                        self._proximo_ticket += 1
                    return decisao
        return DecisaoModeracao(False)

    def tickets_abertos(self) -> list[TicketModeracao]:
        return [ticket for ticket in self.tickets.values() if ticket.status == "aberto"]

    def exportar_logs(self) -> list[dict[str, Any]]:
        return [
            {
                "criado_em": registro.criado_em.isoformat(),
                "servidor_id": registro.servidor_id,
                "canal_id": registro.canal_id,
                "mensagem_id": registro.mensagem_id,
                "usuario_id": registro.usuario_id,
                "regra": registro.decisao.regra,
                "acao": registro.decisao.acao.value if registro.decisao.acao else None,
                "motivo": registro.decisao.motivo,
                "correspondencia": registro.decisao.correspondencia,
            }
            for registro in self.registros
        ]


__all__ = [
    "AcaoModeracao",
    "DecisaoModeracao",
    "MotorAutomoderacao",
    "RegraModeracao",
    "RegistroModeracao",
    "TicketModeracao",
    "normalizar_texto",
]

from __future__ import annotations
import sqlite3
from typing import Any, Iterable
class BancoSQLite:
    def __init__(self, caminho: str = ":memory:"): self.caminho = caminho; self.conexao: sqlite3.Connection | None = None
    def conectar(self) -> "BancoSQLite": self.conexao = sqlite3.connect(self.caminho); self.conexao.row_factory = sqlite3.Row; return self
    def _conn(self) -> sqlite3.Connection:
        if self.conexao is None: self.conectar()
        assert self.conexao is not None; return self.conexao
    def executar(self, sql: str, parametros: Iterable[Any] = ()) -> sqlite3.Cursor: return self._conn().execute(sql, tuple(parametros))
    def buscar(self, sql: str, parametros: Iterable[Any] = ()) -> list[dict[str, Any]]: return [dict(x) for x in self.executar(sql, parametros).fetchall()]
    def commit(self) -> None: self._conn().commit()
    def rollback(self) -> None: self._conn().rollback()
    def fechar(self) -> None:
        if self.conexao: self.conexao.close(); self.conexao = None

"""Catálogo runtime da API Pimcord para a PimcordIA Neural.

O catálogo é derivado da instalação atual, limitado a símbolos públicos e
serializável. Ele não executa funções nem importa módulos opcionais de rede.
"""
from __future__ import annotations

import importlib
import inspect
from types import ModuleType
from typing import Any, Iterable

MODULOS_PUBLICOS = (
    "pimcord",
    "pimcord.comandos",
    "pimcord.discord.modelos",
    "pimcord.discord.recursos",
    "pimcord.interacoes.modelos",
    "pimcord.permissoes",
    "pimcord.economia",
    "pimcord.tarefas",
    "pimcord.extensoes",
)


def _assinatura(valor: Any) -> str | None:
    try:
        return str(inspect.signature(valor))
    except (TypeError, ValueError):
        return None


def _entrada(nome: str, valor: Any) -> dict[str, Any]:
    item: dict[str, Any] = {
        "nome": nome,
        "tipo": "classe" if inspect.isclass(valor) else "funcao" if callable(valor) else "objeto",
        "doc": (inspect.getdoc(valor) or "").splitlines()[0][:400] if inspect.getdoc(valor) else "",
        "assinatura": _assinatura(valor),
    }
    if inspect.isclass(valor):
        metodos: dict[str, str | None] = {}
        for atributo in dir(valor):
            if atributo.startswith("_"):
                continue
            membro = getattr(valor, atributo, None)
            if callable(membro):
                metodos[atributo] = _assinatura(membro)
        item["metodos"] = dict(sorted(metodos.items())[:200])
    return item


def catalogar(modulos: Iterable[str] = MODULOS_PUBLICOS) -> dict[str, Any]:
    resultado: dict[str, Any] = {"modulos": {}, "versao": None}
    for nome_modulo in modulos:
        try:
            modulo: ModuleType = importlib.import_module(nome_modulo)
        except Exception:
            continue
        simbolos: dict[str, Any] = {}
        for nome, valor in sorted(vars(modulo).items()):
            modulo_do_simbolo = getattr(valor, "__module__", nome_modulo)
            pertence_ao_pacote = modulo_do_simbolo == nome_modulo or modulo_do_simbolo.startswith("pimcord.")
            if nome.startswith("_") or not pertence_ao_pacote:
                continue
            simbolos[nome] = _entrada(nome, valor)
        resultado["modulos"][nome_modulo] = simbolos
        if nome_modulo == "pimcord":
            resultado["versao"] = getattr(modulo, "__version__", None)
    return resultado


def resumo_catalogo(catalogo: dict[str, Any] | None = None) -> str:
    catalogo = catalogo or catalogar()
    linhas = [f"Versão Pimcord: {catalogo.get('versao') or 'desconhecida'}"]
    for modulo, simbolos in catalogo.get("modulos", {}).items():
        for nome, item in simbolos.items():
            assinatura = item.get("assinatura") or ""
            metodos = ", ".join(item.get("metodos", {}))
            linhas.append(f"{modulo}.{nome}{assinatura}" + (f"; métodos: {metodos}" if metodos else ""))
    return "\n".join(linhas)

"""Sistema de comandos avançados do Pimcord."""
from __future__ import annotations

import inspect
import time
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, get_args, get_origin, get_type_hints
from ..nucleo import ComandoInvalido, ErroDePermissao

Callback = Callable[..., Awaitable[Any]]

@dataclass(slots=True)
class Cooldown:
    chamadas: int
    por: float
    _usos: dict[str, list[float]] = field(default_factory=dict)
    def verificar(self, chave: str) -> bool:
        agora = time.monotonic()
        usos = [t for t in self._usos.get(chave, []) if agora - t < self.por]
        if len(usos) >= self.chamadas:
            self._usos[chave] = usos
            return False
        usos.append(agora); self._usos[chave] = usos
        return True

def limitar(chamadas: int, por: float) -> Callable[[Callback], Callback]:
    def decorar(callback: Callback) -> Callback:
        setattr(callback, "__pimcord_cooldown__", Cooldown(chamadas, por)); return callback
    return decorar

def autocomplete(funcao: Callable[[Any], Any]) -> Callable[[Callback], Callback]:
    """Marca uma função que fornece sugestões para uma opção slash."""
    def decorar(callback: Callback) -> Callback:
        setattr(callback, "__pimcord_autocomplete__", funcao)
        return callback
    return decorar


def verificar(check: Callable[[Any], bool | Awaitable[bool]]) -> Callable[[Callback], Callback]:
    def decorar(callback: Callback) -> Callback:
        checks = list(getattr(callback, "__pimcord_checks__", [])); checks.append(check)
        setattr(callback, "__pimcord_checks__", checks); return callback
    return decorar

def converter(tipo: type) -> Callable[[str], Any]:
    if tipo is str: return str
    if tipo is int: return int
    if tipo is float: return float
    if tipo is bool: return lambda valor: valor.lower() in {"1", "sim", "true", "verdadeiro", "on"}
    return tipo

async def preparar_argumentos(callback: Callback, argumentos: tuple[str, ...]) -> tuple[Any, ...]:
    assinatura = inspect.signature(callback); parametros = list(assinatura.parameters.values())[1:]
    hints = get_type_hints(callback); resultado: list[Any] = []; posicao = 0
    for parametro in parametros:
        tipo = hints.get(parametro.name, str); origem = get_origin(tipo)
        if origem is not None and type(None) in get_args(tipo): tipo = next((x for x in get_args(tipo) if x is not type(None)), str)
        if parametro.kind is parametro.VAR_POSITIONAL:
            while posicao < len(argumentos):
                try: resultado.append(converter(tipo)(argumentos[posicao]))
                except Exception as erro: raise ComandoInvalido(f"Não consegui converter '{argumentos[posicao]}'.") from erro
                posicao += 1
            continue
        if posicao >= len(argumentos):
            if parametro.default is not inspect.Parameter.empty: resultado.append(parametro.default); continue
            raise ComandoInvalido(f"Falta o argumento obrigatório '{parametro.name}'.")
        valor = argumentos[posicao] if parametro.kind is not parametro.KEYWORD_ONLY else " ".join(argumentos[posicao:])
        posicao = len(argumentos) if parametro.kind is parametro.KEYWORD_ONLY else posicao + 1
        try: resultado.append(converter(tipo)(valor))
        except Exception as erro: raise ComandoInvalido(f"O argumento '{parametro.name}' é inválido.") from erro
    if posicao < len(argumentos): raise ComandoInvalido("Foram enviados argumentos demais.")
    return tuple(resultado)

async def executar_checks(callback: Callback, contexto: Any) -> None:
    for check in getattr(callback, "__pimcord_checks__", []):
        resultado = check(contexto)
        if inspect.isawaitable(resultado): resultado = await resultado
        if not resultado: raise ErroDePermissao("Você não tem permissão para usar este comando.")
    cooldown = getattr(callback, "__pimcord_cooldown__", None)
    if cooldown is not None:
        autor = getattr(getattr(contexto, "autor", None), "id", "global")
        if not cooldown.verificar(str(autor)): raise ComandoInvalido("Este comando está em cooldown.")

@dataclass(slots=True)
class Subcomando:
    nome: str
    callback: Callback
    descricao: str = "Subcomando Pimcord"
    opcoes: list[dict[str, Any]] = field(default_factory=list)

    def para_dict(self) -> dict[str, Any]:
        dados: dict[str, Any] = {
            "type": 1,
            "name": self.nome,
            "description": self.descricao[:100],
        }
        if self.opcoes:
            dados["options"] = self.opcoes
        return dados


@dataclass(slots=True)
class SubgrupoDeComandos:
    nome: str
    descricao: str = "Subgrupo de comandos Pimcord"
    comandos: dict[str, Subcomando] = field(default_factory=dict)

    def subcomando(
        self,
        nome: str,
        *,
        descricao: str = "Subcomando Pimcord",
        opcoes: list[dict[str, Any]] | None = None,
    ) -> Callable[[Callback], Callback]:
        def registrar(callback: Callback) -> Callback:
            self.comandos[nome] = Subcomando(nome, callback, descricao, list(opcoes or []))
            return callback
        return registrar

    def para_dict(self) -> dict[str, Any]:
        return {
            "type": 2,
            "name": self.nome,
            "description": self.descricao[:100],
            "options": [comando.para_dict() for comando in self.comandos.values()],
        }


@dataclass(slots=True)
class GrupoDeComandos:
    nome: str
    callback: Callback
    descricao: str = "Grupo de comandos Pimcord"
    comandos: dict[str, Subcomando | SubgrupoDeComandos] = field(default_factory=dict)

    def subcomando(
        self,
        nome: str,
        *,
        descricao: str = "Subcomando Pimcord",
        opcoes: list[dict[str, Any]] | None = None,
    ) -> Callable[[Callback], Callback]:
        def registrar(callback: Callback) -> Callback:
            self.comandos[nome] = Subcomando(nome, callback, descricao, list(opcoes or []))
            return callback
        return registrar

    def subgrupo(self, nome: str, *, descricao: str = "Subgrupo de comandos Pimcord") -> Callable[[Callable[..., Any]], SubgrupoDeComandos]:
        def registrar(callback: Callable[..., Any]) -> SubgrupoDeComandos:
            subgrupo = SubgrupoDeComandos(nome, descricao)
            self.comandos[nome] = subgrupo
            return subgrupo
        return registrar

    def para_dict(self) -> dict[str, Any]:
        return {
            "type": 1,
            "name": self.nome,
            "description": self.descricao[:100],
            "options": [comando.para_dict() for comando in self.comandos.values()],
        }

__all__ = ["Cooldown", "limitar", "verificar", "autocomplete", "preparar_argumentos", "executar_checks", "Subcomando", "SubgrupoDeComandos", "GrupoDeComandos"]

"""Sistema de comandos avançados do Pimcord."""
from __future__ import annotations

import inspect
import time
from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, get_args, get_origin, get_type_hints

from .nucleo import ComandoInvalido, ErroDePermissao

Callback = Callable[..., Awaitable[Any]]


@dataclass(slots=True)
class Cooldown:
    chamadas: int
    por: float
    _usos: dict[str, list[float]] = field(default_factory=dict)

    def verificar(self, chave: str) -> bool:
        agora = time.monotonic()
        usos = [valor for valor in self._usos.get(chave, []) if agora - valor < self.por]
        if len(usos) >= self.chamadas:
            self._usos[chave] = usos
            return False
        usos.append(agora)
        self._usos[chave] = usos
        return True


def limitar(chamadas: int, por: float) -> Callable[[Callback], Callback]:
    """Limita o número de execuções de um comando por janela de tempo."""
    def decorar(callback: Callback) -> Callback:
        setattr(callback, "__pimcord_cooldown__", Cooldown(chamadas, por))
        return callback
    return decorar


def autocomplete(funcao: Callable[[Any], Any]) -> Callable[[Callback], Callback]:
    """Marca uma função que fornece sugestões para uma opção slash."""
    def decorar(callback: Callback) -> Callback:
        setattr(callback, "__pimcord_autocomplete__", funcao)
        return callback
    return decorar


def verificar(check: Callable[[Any], bool | Awaitable[bool]]) -> Callable[[Callback], Callback]:
    """Adiciona uma função de autorização executada antes do comando."""
    def decorar(callback: Callback) -> Callback:
        checks = list(getattr(callback, "__pimcord_checks__", []))
        checks.append(check)
        setattr(callback, "__pimcord_checks__", checks)
        return callback
    return decorar


def converter(tipo: type) -> Callable[[str], Any]:
    """Converte argumentos comuns e produz erro legível em português."""
    if tipo is str:
        return str
    if tipo is int:
        return int
    if tipo is float:
        return float
    if tipo is bool:
        return lambda valor: valor.lower() in {"1", "sim", "true", "verdadeiro", "on"}
    return tipo


async def preparar_argumentos(callback: Callback, argumentos: tuple[str, ...]) -> tuple[Any, ...]:
    """Converte argumentos de acordo com as anotações da função."""
    assinatura = inspect.signature(callback)
    parametros = list(assinatura.parameters.values())[1:]
    hints = get_type_hints(callback)
    resultado: list[Any] = []
    posicao = 0
    for parametro in parametros:
        tipo = hints.get(parametro.name, str)
        origem = get_origin(tipo)
        if origem is not None and type(None) in get_args(tipo):
            tipo = next((item for item in get_args(tipo) if item is not type(None)), str)
        if parametro.kind is parametro.VAR_POSITIONAL:
            while posicao < len(argumentos):
                try:
                    resultado.append(converter(tipo)(argumentos[posicao]))
                except Exception as erro:
                    raise ComandoInvalido(f"Não consegui converter '{argumentos[posicao]}' para {tipo.__name__}.") from erro
                posicao += 1
            continue
        if posicao >= len(argumentos):
            if parametro.default is not inspect.Parameter.empty:
                resultado.append(parametro.default)
                continue
            raise ComandoInvalido(f"Falta o argumento obrigatório '{parametro.name}'.")
        valor = argumentos[posicao] if parametro.kind is not parametro.KEYWORD_ONLY else " ".join(argumentos[posicao:])
        posicao = len(argumentos) if parametro.kind is parametro.KEYWORD_ONLY else posicao + 1
        try:
            resultado.append(converter(tipo)(valor))
        except Exception as erro:
            raise ComandoInvalido(f"O argumento '{parametro.name}' não é um {getattr(tipo, '__name__', tipo)} válido.") from erro
    if posicao < len(argumentos):
        raise ComandoInvalido("Foram enviados argumentos demais para este comando.")
    return tuple(resultado)


async def executar_checks(callback: Callback, contexto: Any) -> None:
    for check in getattr(callback, "__pimcord_checks__", []):
        resultado = check(contexto)
        if inspect.isawaitable(resultado):
            resultado = await resultado
        if not resultado:
            raise ErroDePermissao("Você não tem permissão para usar este comando.")
    cooldown = getattr(callback, "__pimcord_cooldown__", None)
    if cooldown is not None:
        autor = getattr(getattr(contexto, "autor", None), "id", "global")
        if not cooldown.verificar(str(autor)):
            raise ComandoInvalido("Este comando está em cooldown. Tente novamente em instantes.")


@dataclass(slots=True)
class GrupoDeComandos:
    nome: str
    callback: Callback
    comandos: dict[str, Callback] = field(default_factory=dict)

    def subcomando(self, nome: str) -> Callable[[Callback], Callback]:
        def registrar(callback: Callback) -> Callback:
            self.comandos[nome] = callback
            return callback
        return registrar

"""Negociação DAVE/MLS com backend criptográfico injetável.

Este módulo implementa somente a máquina de protocolo e o enquadramento das
mensagens. A criptografia MLS/DAVE real continua delegada a um backend externo
compatível; nenhum algoritmo parcial é apresentado como E2EE completo.
"""
from __future__ import annotations

import struct
from dataclasses import dataclass
from enum import IntEnum, StrEnum
from typing import Protocol, FrozenSet


class OpcodeDAVE(IntEnum):
    PREPARAR_TRANSICAO = 21
    EXECUTAR_TRANSICAO = 22
    PRONTO_PARA_TRANSICAO = 23
    PREPARAR_EPOCA = 24
    REMETENTE_EXTERNO = 25
    PACOTE_CHAVE = 26
    PROPOSTAS = 27
    COMMIT_WELCOME = 28
    ANUNCIAR_COMMIT = 29
    WELCOME = 30
    COMMIT_WELCOME_INVALIDO = 31


class TipoMensagemMLS(StrEnum):
    """Tipos explícitos aceitos pela sessão DAVE/libdave."""

    PROPOSTAS = "propostas"
    COMMIT = "commit"
    WELCOME = "welcome"


@dataclass(frozen=True, slots=True)
class MensagemMLSDAVE:
    """Envelope semântico para impedir dispatch MLS por adivinhação de bytes."""

    tipo: TipoMensagemMLS
    dados: bytes
    usuarios_reconhecidos: FrozenSet[str] = frozenset()

    def __post_init__(self) -> None:
        if not self.dados:
            raise ValueError("Mensagem MLS vazia")
        if any(not isinstance(usuario, str) or not usuario for usuario in self.usuarios_reconhecidos):
            raise ValueError("usuarios_reconhecidos deve conter IDs não vazios")


class BackendDAVE(Protocol):
    versao_maxima: int

    def gerar_key_package(self) -> bytes: ...
    def processar_mensagem_mls(self, dados: bytes) -> None: ...
    def preparar_epoca(self, epoca: int) -> None: ...
    def exportar_chave_remetente(self, remetente_id: str) -> bytes: ...


class BackendDAVEEnvelope(Protocol):
    """Operações semânticas exigidas para encaminhar mensagens MLS com segurança."""

    def processar_propostas(self, dados: bytes) -> None: ...
    def processar_commit(self, dados: bytes) -> None: ...
    def processar_welcome(self, dados: bytes) -> None: ...


class BackendDAVEReal(BackendDAVE, BackendDAVEEnvelope, Protocol):
    """Contrato adicional exigido por um adaptador E2EE realmente integrado.

    Declarar este protocolo não implementa criptografia. Ele apenas torna visível
    a superfície que um binding libdave auditado precisa fornecer antes que o
    Pimcord possa habilitar mídia protegida.
    """

    e2ee_real: bool

    def cifrar_frame(self, remetente_id: str, frame: bytes) -> bytes: ...
    def decifrar_frame(self, remetente_id: str, frame: bytes) -> bytes: ...
    def autenticador_epoca(self, epoca: int, dados: bytes) -> bytes: ...


@dataclass(frozen=True, slots=True)
class MensagemDAVE:
    opcode: OpcodeDAVE
    payload: bytes = b""
    sequencia: int | None = None

    def serializar(self) -> bytes:
        prefixo = struct.pack(">H", self.sequencia & 0xFFFF) if self.sequencia is not None else b""
        return prefixo + bytes([int(self.opcode)]) + self.payload

    @classmethod
    def desserializar(cls, dados: bytes, *, tem_sequencia: bool = False) -> "MensagemDAVE":
        deslocamento = 0
        sequencia = None
        if tem_sequencia:
            if len(dados) < 3:
                raise ValueError("Mensagem DAVE binária truncada")
            sequencia = struct.unpack(">H", dados[:2])[0]
            deslocamento = 2
        if len(dados) <= deslocamento:
            raise ValueError("Mensagem DAVE sem opcode")
        try:
            opcode = OpcodeDAVE(dados[deslocamento])
        except ValueError as erro:
            raise ValueError(f"Opcode DAVE desconhecido: {dados[deslocamento]}") from erro
        return cls(opcode, dados[deslocamento + 1 :], sequencia)


def validar_backend_dave(backend: BackendDAVE) -> BackendDAVE:
    """Valida a capacidade mínima de um backend MLS/DAVE injetado.

    A função não implementa criptografia; ela evita que um adaptador incompleto
    seja aceito silenciosamente e falhe no meio de uma transição de época.
    """
    versao = getattr(backend, "versao_maxima", None)
    if not isinstance(versao, int) or versao < 1:
        raise TypeError("backend DAVE deve expor versao_maxima inteira positiva")
    obrigatorios = ("gerar_key_package", "processar_mensagem_mls", "preparar_epoca", "exportar_chave_remetente")
    ausentes = [nome for nome in obrigatorios if not callable(getattr(backend, nome, None))]
    if ausentes:
        raise TypeError(f"backend DAVE incompleto; faltam: {', '.join(ausentes)}")
    return backend


def exigir_backend_dave_real(backend: BackendDAVE) -> BackendDAVE:
    """Exige marcadores explícitos de um backend E2EE, sem aceitar simuladores."""
    validar_backend_dave(backend)
    if getattr(backend, "e2ee_real", False) is not True:
        raise TypeError("backend DAVE não foi declarado como E2EE real; use um adaptador MLS auditado")
    obrigatorios = (
        "cifrar_frame",
        "decifrar_frame",
        "autenticador_epoca",
        "processar_propostas",
        "processar_commit",
        "processar_welcome",
    )
    ausentes = [nome for nome in obrigatorios if not callable(getattr(backend, nome, None))]
    if ausentes:
        raise TypeError(f"backend DAVE E2EE incompleto; faltam: {', '.join(ausentes)}")
    return backend


class EstadoDAVE:
    """Máquina de transição DAVE sem operações criptográficas embutidas."""
    def __init__(self, backend: BackendDAVE):
        self.backend = validar_backend_dave(backend)
        self.versao = 0
        self.epoca = 0
        self.transicao_id: int | None = None
        self.pronto = False
        self.em_transicao = False

    def identificar(self) -> dict[str, int]:
        return {"max_dave_protocol_version": int(self.backend.versao_maxima)}

    def receber_preparacao(self, *, versao: int, epoca: int, transicao_id: int) -> bytes | None:
        if versao <= 0 or versao > self.backend.versao_maxima:
            raise ValueError(f"Versão DAVE não suportada: {versao}")
        if epoca < 1:
            raise ValueError("A época DAVE deve ser positiva")
        if epoca < self.epoca:
            raise ValueError("Época DAVE antiga foi rejeitada")
        if epoca == self.epoca and self.transicao_id is not None and transicao_id != self.transicao_id:
            raise ValueError("Transição DAVE conflitante para a época atual")
        self.versao = versao
        self.epoca = epoca
        self.transicao_id = transicao_id
        self.em_transicao = True
        self.pronto = False
        if epoca == 1:
            return self.backend.gerar_key_package()
        self.backend.preparar_epoca(epoca)
        return None

    def receber_mensagem_mls(self, dados: bytes) -> None:
        if not dados:
            raise ValueError("Mensagem MLS vazia")
        self.backend.processar_mensagem_mls(dados)

    def receber_remetente_externo(self, dados: bytes) -> None:
        """Entrega o pacote de external sender ao backend nativo.

        O envelope interno é deliberadamente opaco: o formato pertence ao
        protocolo DAVE/MLS e não pode ser inferido com segurança pelo cliente.
        """
        if not dados:
            raise ValueError("Pacote de remetente externo vazio")
        metodo = getattr(self.backend, "processar_remetente_externo", None)
        if not callable(metodo):
            raise TypeError("backend DAVE não expõe processar_remetente_externo")
        metodo(dados)

    def receber_propostas(self, dados: bytes) -> None:
        if not dados:
            raise ValueError("Propostas MLS vazias")
        metodo = getattr(self.backend, "processar_propostas", None)
        if not callable(metodo):
            raise TypeError("backend DAVE não expõe processar_propostas")
        metodo(dados)

    def receber_commit(self, dados: bytes) -> None:
        if not dados:
            raise ValueError("Commit MLS vazio")
        metodo = getattr(self.backend, "processar_commit", None)
        if not callable(metodo):
            raise TypeError("backend DAVE não expõe processar_commit")
        metodo(dados)

    def receber_welcome(self, dados: bytes) -> None:
        if not dados:
            raise ValueError("Welcome MLS vazio")
        metodo = getattr(self.backend, "processar_welcome", None)
        if not callable(metodo):
            raise TypeError("backend DAVE não expõe processar_welcome")
        metodo(dados)

    def receber_mensagem_mls_tipada(self, mensagem: MensagemMLSDAVE) -> None:
        """Encaminha MLS pelo tipo explícito, sem adivinhar o conteúdo binário."""
        if not isinstance(mensagem, MensagemMLSDAVE):
            raise TypeError("mensagem deve ser MensagemMLSDAVE")
        metodos = {
            TipoMensagemMLS.PROPOSTAS: "processar_propostas",
            TipoMensagemMLS.COMMIT: "processar_commit",
            TipoMensagemMLS.WELCOME: "processar_welcome",
        }
        metodo = getattr(self.backend, metodos[mensagem.tipo], None)
        if not callable(metodo):
            raise TypeError(
                f"backend DAVE não expõe o processador semântico de {mensagem.tipo.value}"
            )
        metodo(mensagem.dados)

    def exportar_chave_remetente(self, remetente_id: str) -> bytes:
        if self.epoca < 1 or self.em_transicao:
            raise RuntimeError("A sessão DAVE ainda não está estabelecida")
        return self.backend.exportar_chave_remetente(remetente_id)

    def marcar_pronto(self) -> MensagemDAVE:
        if not self.em_transicao or self.transicao_id is None:
            raise RuntimeError("Nenhuma transição DAVE foi preparada")
        self.pronto = True
        return MensagemDAVE(OpcodeDAVE.PRONTO_PARA_TRANSICAO, struct.pack(">I", self.transicao_id))

    def executar(self, *, transicao_id: int) -> None:
        if transicao_id != self.transicao_id:
            raise ValueError("transicao_id DAVE inesperado")
        if not self.pronto:
            raise RuntimeError("A sessão ainda não está pronta para a transição DAVE")
        self.em_transicao = False


__all__ = ["OpcodeDAVE", "TipoMensagemMLS", "MensagemMLSDAVE", "BackendDAVE", "BackendDAVEEnvelope", "BackendDAVEReal", "MensagemDAVE", "EstadoDAVE", "validar_backend_dave", "exigir_backend_dave_real"]

