from __future__ import annotations

import time
from typing import Any

from .banco import BancoSQLite


class EconomiaSQLite:
    def __init__(self, caminho: str = "economia.sqlite3", *, saldo_inicial: int = 0, diaria: int = 100):
        self.banco = BancoSQLite(caminho).conectar()
        self.saldo_inicial = saldo_inicial
        self.valor_diaria = diaria
        self.banco.executar(
            "CREATE TABLE IF NOT EXISTS economia_usuarios (usuario_id TEXT PRIMARY KEY, saldo INTEGER NOT NULL DEFAULT 0, ultima_diaria REAL)"
        )
        self.banco.commit()

    def _garantir(self, usuario_id: str) -> None:
        self.banco.executar(
            "INSERT OR IGNORE INTO economia_usuarios (usuario_id, saldo, ultima_diaria) VALUES (?, ?, NULL)",
            (str(usuario_id), self.saldo_inicial),
        )
        self.banco.commit()

    def saldo(self, usuario_id: str) -> int:
        self._garantir(usuario_id)
        linha = self.banco.buscar("SELECT saldo FROM economia_usuarios WHERE usuario_id = ?", (str(usuario_id),))[0]
        return int(linha["saldo"])

    def diaria(self, usuario_id: str, *, agora: float | None = None) -> int:
        agora = time.time() if agora is None else agora
        self._garantir(usuario_id)
        linhas = self.banco.buscar("SELECT saldo, ultima_diaria FROM economia_usuarios WHERE usuario_id = ?", (str(usuario_id),))
        linha = linhas[0]
        ultima = linha["ultima_diaria"]
        if ultima is not None and agora - float(ultima) < 86400:
            raise ValueError("A recompensa diária ainda está em cooldown.")
        novo_saldo = int(linha["saldo"]) + self.valor_diaria
        self.banco.executar("UPDATE economia_usuarios SET saldo = ?, ultima_diaria = ? WHERE usuario_id = ?", (novo_saldo, agora, str(usuario_id)))
        self.banco.commit()
        return novo_saldo

    def transferir(self, remetente: str, destinatario: str, valor: int) -> tuple[int, int]:
        if not isinstance(valor, int) or isinstance(valor, bool) or valor <= 0:
            raise ValueError("O valor precisa ser um inteiro positivo.")
        if str(remetente) == str(destinatario):
            raise ValueError("Não é possível transferir para si mesmo.")
        self._garantir(remetente)
        self._garantir(destinatario)
        origem = self.saldo(remetente)
        if origem < valor:
            raise ValueError("Saldo insuficiente.")
        self.banco.executar("UPDATE economia_usuarios SET saldo = saldo - ? WHERE usuario_id = ?", (valor, str(remetente)))
        self.banco.executar("UPDATE economia_usuarios SET saldo = saldo + ? WHERE usuario_id = ?", (valor, str(destinatario)))
        self.banco.commit()
        return self.saldo(remetente), self.saldo(destinatario)

    def ranking(self, limite: int = 10) -> list[dict[str, Any]]:
        if not isinstance(limite, int) or limite <= 0 or limite > 100:
            raise ValueError("O limite deve estar entre 1 e 100.")
        return self.banco.buscar("SELECT usuario_id, saldo FROM economia_usuarios ORDER BY saldo DESC, usuario_id ASC LIMIT ?", (limite,))

    def fechar(self) -> None:
        self.banco.fechar()


__all__ = ["EconomiaSQLite"]

"""Cliente REST assíncrono e abrangente do Discord para o Pimcord."""
from __future__ import annotations

import asyncio
import json
import logging
from collections import defaultdict
from io import IOBase
from typing import Any, AsyncIterator, Iterable
from urllib.parse import urlencode

import aiohttp

from ..nucleo import ErroDaAPI, ErroDeConfiguracao, RateLimitado
from ..seguranca import FiltroSegredos


class ClienteHTTP:
    """Transporte REST com retries, buckets locais, JSON e multipart.

    Os métodos de recurso são apenas uma camada ergonômica sobre ``requisitar``;
    ``requisitar`` continua disponível para endpoints novos do Discord.
    """

    def __init__(self, token: str, *, versao: int = 10, timeout: float = 30.0):
        if not isinstance(token, str):
            raise ErroDeConfiguracao("O token do bot precisa ser texto.")
        token = "".join(
            caractere for caractere in token
            if not caractere.isspace() and 32 <= ord(caractere) != 127
        )
        if not token:
            raise ErroDeConfiguracao("Token vazio. Cole o token do bot novamente.")
        self.token = token
        self.versao = versao
        self.base_url = f"https://discord.com/api/v{versao}"
        self.timeout = aiohttp.ClientTimeout(total=timeout)
        self._sessao: aiohttp.ClientSession | None = None
        self._locks: defaultdict[str, asyncio.Lock] = defaultdict(asyncio.Lock)
        self._limites: dict[str, tuple[int, float]] = {}
        self.logger = logging.getLogger("pimcord.http")
        self.logger.addFilter(FiltroSegredos([token]))

    async def abrir(self) -> None:
        if self._sessao is None or self._sessao.closed:
            self._sessao = aiohttp.ClientSession(
                timeout=self.timeout,
                headers={
                    "Authorization": f"Bot {self.token}",
                    "User-Agent": "Pimcord/0.7.0 (+https://github.com/pimcord/pimcord)",
                },
            )

    async def fechar(self) -> None:
        if self._sessao and not self._sessao.closed:
            await self._sessao.close()

    async def requisitar(
        self,
        metodo: str,
        rota: str,
        *,
        json: Any = None,
        dados: Any = None,
        arquivos: Iterable[Any] | None = None,
        campos_multipart: dict[str, Any] | None = None,
        parametros: dict[str, Any] | None = None,
        motivo: str | None = None,
        cabecalhos: dict[str, str] | None = None,
        tentativas: int = 3,
        bruto: bool = False,
    ) -> Any:
        """Executa uma chamada; aceita JSON, dados e multipart sem rede em testes quando sessão é substituída."""
        if tentativas < 1:
            raise ValueError("tentativas deve ser pelo menos 1")
        if motivo is not None:
            if not isinstance(motivo, str):
                raise TypeError("motivo deve ser texto")
            if len(motivo) > 512:
                raise ValueError("motivo deve ter no máximo 512 caracteres")
        await self.abrir()
        assert self._sessao is not None
        rota_base = rota.split("?", 1)[0]
        chave = rota_base
        headers = dict(cabecalhos or {})
        if motivo is not None:
            headers["X-Audit-Log-Reason"] = motivo
        corpo = dados
        if arquivos is not None:
            formulario = aiohttp.FormData()
            if json is not None:
                formulario.add_field("payload_json", __import__("json").dumps(json, ensure_ascii=False))
            for campo, valor in (campos_multipart or {}).items():
                formulario.add_field(str(campo), str(valor))
            for indice, item in enumerate(arquivos):
                campo = f"files[{indice}]"
                nome = getattr(item, "nome", None) or getattr(item, "name", None) or f"arquivo_{indice}"
                conteudo = item
                if isinstance(item, tuple) and len(item) >= 3:
                    campo, nome, conteudo = item[0], item[1], item[2]
                elif isinstance(item, tuple) and len(item) >= 2:
                    nome, conteudo = item[0], item[1]
                if isinstance(conteudo, (bytes, bytearray)):
                    formulario.add_field(campo, conteudo, filename=str(nome))
                elif isinstance(conteudo, IOBase):
                    formulario.add_field(campo, conteudo, filename=str(nome))
                else:
                    formulario.add_field(campo, str(conteudo), filename=str(nome))
            corpo = formulario
            json = None
        url = self.base_url + rota
        for tentativa in range(tentativas):
            async with self._locks[chave]:
                async with self._sessao.request(metodo, url, json=json, data=corpo, params=parametros, headers=headers) as resposta:
                    restante = resposta.headers.get("X-RateLimit-Remaining")
                    reset = resposta.headers.get("X-RateLimit-Reset-After")
                    if restante is not None and reset is not None:
                        self._limites[chave] = (int(restante), float(reset))
                    if resposta.status == 429:
                        texto_rate_limit = await resposta.text()
                        try:
                            dados_erro = json_module_loads(texto_rate_limit) if texto_rate_limit else {}
                        except Exception:
                            dados_erro = {}
                        if not isinstance(dados_erro, dict):
                            dados_erro = {}
                        espera_bruta = dados_erro.get("retry_after", resposta.headers.get("Retry-After", resposta.headers.get("X-RateLimit-Reset-After", 1)))
                        try:
                            espera = float(espera_bruta)
                        except (TypeError, ValueError):
                            espera = 1.0
                        if tentativa + 1 == tentativas:
                            raise RateLimitado(f"Rate limitado; tente novamente em {espera}s", espera=espera, global_=bool(dados_erro.get("global", False)), rota=rota)
                        await asyncio.sleep(espera)
                        continue
                    if resposta.status in {500, 502, 503, 504} and tentativa + 1 < tentativas:
                        await asyncio.sleep(2 ** tentativa)
                        continue
                    if resposta.status >= 400:
                        texto = await resposta.text()
                        try:
                            erro = json_module_loads(texto)
                        except Exception:
                            erro = {"message": texto[:500]}
                        raise ErroDaAPI(f"Discord HTTP {resposta.status}: {erro.get('message', erro) if isinstance(erro, dict) else erro}", status=resposta.status, codigo=erro.get("code") if isinstance(erro, dict) else None, erros=erro.get("errors") if isinstance(erro, dict) else None, rota=rota, metodo=metodo)
                    if resposta.status == 204:
                        return None
                    if bruto:
                        return await resposta.read()
                    texto = await resposta.text()
                    if not texto:
                        return None
                    try:
                        return json_module_loads(texto)
                    except Exception:
                        return texto
        raise ErroDaAPI("Falha inesperada na requisição REST", rota=rota, metodo=metodo)

    async def endpoint(self, metodo: str, rota: str, **kwargs: Any) -> Any:
        """Alias explícito para permitir endpoints futuros sem alterar o cliente."""
        return await self.requisitar(metodo, rota, **kwargs)

    async def paginar(self, metodo: str, rota: str, *, limite: int = 100, campo: str | None = None, antes_de: str | None = None, depois_de: str | None = None, **kwargs: Any) -> AsyncIterator[Any]:
        """Percorre endpoints baseados em ``before`` ou ``after`` sem perder filtros entre páginas.

        A iteração encerra com segurança quando o endpoint devolve um cursor repetido,
        evitando consumo infinito diante de um servidor ou mock inconsistente.
        """
        restante = max(0, int(limite))
        if antes_de is not None and depois_de is not None:
            raise ValueError("use antes_de ou depois_de, não ambos")
        parametros_base = dict(kwargs.pop("parametros", {}) or {})
        cursor = antes_de if antes_de is not None else depois_de
        nome_cursor = "after" if depois_de is not None else "before"
        cursor_anterior: str | None = None
        while restante:
            quantidade = min(restante, 100)
            parametros = dict(parametros_base)
            parametros["limit"] = quantidade
            if cursor:
                parametros[nome_cursor] = cursor
            pagina = await self.requisitar(metodo, rota, parametros=parametros, **kwargs)
            itens = pagina.get(campo, []) if campo and isinstance(pagina, dict) else pagina
            if not isinstance(itens, (list, tuple)) or not itens:
                return
            cursor_pagina: str | None = None
            for item in itens:
                yield item
                restante -= 1
                if isinstance(item, dict) and item.get("id") is not None:
                    cursor_pagina = str(item["id"])
                if not restante:
                    return
            if cursor_pagina is None or cursor_pagina == cursor_anterior:
                return
            cursor_anterior = cursor_pagina
            cursor = cursor_pagina

    async def gateway(self) -> str:
        return (await self.requisitar("GET", "/gateway/bot"))["url"]

    # Mensagens e canais
    async def enviar_mensagem(self, canal_id: str, conteudo: str = "", *, embed: dict[str, Any] | None = None, embeds: list[dict[str, Any]] | None = None, view: Any = None, arquivos: Iterable[Any] | None = None, permitido_mencionar: dict[str, Any] | None = None, tts: bool = False, reply: str | None = None) -> dict[str, Any]:
        corpo: dict[str, Any] = {"content": conteudo, "tts": tts}
        if embed is not None: corpo["embeds"] = [embed]
        elif embeds is not None: corpo["embeds"] = embeds
        if view is not None and hasattr(view, "para_componentes"): corpo["components"] = view.para_componentes()
        if permitido_mencionar is not None: corpo["allowed_mentions"] = permitido_mencionar
        if reply is not None: corpo["message_reference"] = {"message_id": str(reply)}
        return await self.requisitar("POST", f"/channels/{canal_id}/messages", json=corpo, arquivos=arquivos)

    async def buscar_mensagem(self, canal_id: str, mensagem_id: str) -> dict[str, Any]: return await self.requisitar("GET", f"/channels/{canal_id}/messages/{mensagem_id}")
    async def editar_mensagem(self, canal_id: str, mensagem_id: str, **dados: Any) -> dict[str, Any]: return await self.requisitar("PATCH", f"/channels/{canal_id}/messages/{mensagem_id}", json=dados)
    async def apagar_mensagem(self, canal_id: str, mensagem_id: str, *, motivo: str | None = None) -> None: await self.requisitar("DELETE", f"/channels/{canal_id}/messages/{mensagem_id}", motivo=motivo)
    async def indicar_digitacao(self, canal_id: str) -> None: await self.requisitar("POST", f"/channels/{canal_id}/typing")
    async def publicar_mensagem(self, canal_id: str, mensagem_id: str) -> dict[str, Any]: return await self.requisitar("POST", f"/channels/{canal_id}/messages/{mensagem_id}/crosspost")
    async def encerrar_enquete(self, canal_id: str, mensagem_id: str) -> dict[str, Any]: return await self.requisitar("POST", f"/channels/{canal_id}/polls/{mensagem_id}/expire")
    async def listar_usuarios_reacao(self, canal_id: str, mensagem_id: str, emoji: str, *, limite: int = 25, depois_de: str | None = None) -> list[dict[str, Any]]:
        """Lista usuários que usaram um emoji em uma mensagem."""
        if not 1 <= limite <= 100:
            raise ValueError("limite de reações deve estar entre 1 e 100")
        parametros: dict[str, Any] = {"limit": limite}
        if depois_de is not None:
            parametros["after"] = str(depois_de)
        return await self.requisitar("GET", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}", parametros=parametros)
    async def adicionar_reacao(self, canal_id: str, mensagem_id: str, emoji: str, *, usuario_id: str = "@me") -> None: await self.requisitar("PUT", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}/{usuario_id}")
    async def remover_reacao(self, canal_id: str, mensagem_id: str, emoji: str, *, usuario_id: str = "@me") -> None: await self.requisitar("DELETE", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}/{usuario_id}")
    async def listar_reacoes(self, canal_id: str, mensagem_id: str, emoji: str, **parametros: Any) -> list[dict[str, Any]]: return await self.requisitar("GET", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}", parametros=parametros)
    async def limpar_reacoes(self, canal_id: str, mensagem_id: str, emoji: str | None = None) -> None: await self.requisitar("DELETE", f"/channels/{canal_id}/messages/{mensagem_id}/reactions" + (f"/{emoji}" if emoji else ""))
    async def adicionar_reacao_atual(self, canal_id: str, mensagem_id: str, emoji: str) -> None: await self.requisitar("PUT", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}/@me")
    async def remover_reacao_atual(self, canal_id: str, mensagem_id: str, emoji: str) -> None: await self.requisitar("DELETE", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}/@me")
    async def limpar_reacoes_emoji(self, canal_id: str, mensagem_id: str, emoji: str) -> None: await self.requisitar("DELETE", f"/channels/{canal_id}/messages/{mensagem_id}/reactions/{emoji}")
    async def limpar_todas_reacoes(self, canal_id: str, mensagem_id: str) -> None:
        """Remove todas as reações de uma mensagem."""
        await self.requisitar("DELETE", f"/channels/{canal_id}/messages/{mensagem_id}/reactions")
    async def buscar_mensagens(self, canal_id: str, *, limite: int = 50, antes_de: str | None = None, depois_de: str | None = None, em_torno_de: str | None = None) -> list[dict[str, Any]]:
        parametros: dict[str, Any] = {"limit": max(1, min(int(limite), 100))}
        if antes_de is not None: parametros["before"] = str(antes_de)
        if depois_de is not None: parametros["after"] = str(depois_de)
        if em_torno_de is not None: parametros["around"] = str(em_torno_de)
        return await self.requisitar("GET", f"/channels/{canal_id}/messages", parametros=parametros)
    async def apagar_mensagens(self, canal_id: str, mensagens: list[str], *, motivo: str | None = None) -> None:
        ids = [str(item) for item in mensagens]
        if not ids: return
        if len(ids) == 1: return await self.apagar_mensagem(canal_id, ids[0], motivo=motivo)
        if len(ids) > 100: raise ValueError("O Discord aceita no máximo 100 mensagens por exclusão em lote.")
        await self.requisitar("POST", f"/channels/{canal_id}/messages/bulk-delete", json={"messages": ids}, motivo=motivo)
    async def obter_canal(self, canal_id: str) -> dict[str, Any]: return await self.requisitar("GET", f"/channels/{canal_id}")
    async def listar_votantes_enquete(self, canal_id: str, mensagem_id: str, resposta_id: str, *, limite: int = 25, depois_de: str | None = None) -> list[dict[str, Any]]:
        """Lista usuários que votaram em uma resposta de enquete."""
        if not 1 <= limite <= 100:
            raise ValueError("limite de votantes deve estar entre 1 e 100")
        parametros: dict[str, Any] = {"limit": limite}
        if depois_de is not None:
            parametros["after"] = str(depois_de)
        return await self.requisitar("GET", f"/channels/{canal_id}/polls/{mensagem_id}/answers/{resposta_id}", parametros=parametros)

from __future__ import annotations
from typing import Any, Iterable
from ..nucleo import Embed, ErroDeConfiguracao

class Interacao:
    def __init__(self, dados: dict[str, Any], cliente: Any):
        self.id = str(dados["id"]); self.token = dados["token"]; self.dados = dados; self.cliente = cliente
        self.application_id = str(dados.get("application_id", ""))
        data = dados.get("data", {})
        self.tipo = int(dados.get("type", 0))
        self.custom_id = data.get("custom_id")
        self.valores = list(data.get("values", []))
        self.nome_comando = str(data.get("name", ""))
        self.opcoes_brutas = list(data.get("options", []) or [])
        self.grupo_subcomando: str | None = None
        self.subcomando: str | None = None
        self.opcoes: dict[str, Any] = {}
        self._ler_opcoes_aninhadas(self.opcoes_brutas)
        self.dados_brutos = dados
        self.permissoes_aplicacao = dados.get("app_permissions")
        self.entitlements: list[dict[str, Any]] = list(dados.get("entitlements", []) or [])
        self.proprietarios_autorizadores: dict[str, str] = dict(dados.get("authorizing_integration_owners", {}) or {})
        self.contexto_interacao = dados.get("context")
        self.limite_anexos: int | None = dados.get("attachment_size_limit")
        self.canal_resolvido: dict[str, Any] | None = None
        self.canal_id: str | None = str(dados.get("channel_id")) if dados.get("channel_id") is not None else None
        self.servidor_id: str | None = str(dados.get("guild_id")) if dados.get("guild_id") is not None else None
        resolvidos = data.get("resolved", {}) or {}
        canais_resolvidos = resolvidos.get("channels", {}) if isinstance(resolvidos, dict) else {}
        if isinstance(canais_resolvidos, dict):
            canal = next(iter(canais_resolvidos.values()), None)
            if isinstance(canal, dict):
                self.canal_resolvido = canal
                if self.canal_id is None and canal.get("id") is not None:
                    self.canal_id = str(canal["id"])
                if self.servidor_id is None and canal.get("guild_id") is not None:
                    self.servidor_id = str(canal["guild_id"])
                if self.permissoes_aplicacao is None:
                    self.permissoes_aplicacao = canal.get("app_permissions")
        membro = dados.get("member", {}) or {}
        self.membro = membro
        usuario = membro.get("user", {}) or dados.get("user", {}) or {}
        self.usuario_id = str(usuario.get("id", ""))

    @property
    def canal(self) -> Any:
        """Retorna o canal resolvido como modelo Canal quando o Discord o fornece."""
        if not self.canal_id:
            return None
        from ..discord.modelos import Canal
        dados = self.canal_resolvido or {}
        return Canal(
            id=str(self.canal_id),
            cliente=self.cliente,
            nome=dados.get("name"),
            tipo=dados.get("type"),
            servidor_id=self.servidor_id or dados.get("guild_id"),
        )

    @property
    def entitlements_modelados(self) -> list[Any]:
        """Entitlements da interação convertidos no modelo público quando possível."""
        from ..discord.recursos import Entitlement
        return [Entitlement.de_dict(item) for item in self.entitlements if isinstance(item, dict)]

    @property
    def authorizing_integration_owners(self) -> dict[str, str]:
        """Alias oficial para integrações que autorizaram a interação."""
        return self.proprietarios_autorizadores

    @property
    def attachment_size_limit(self) -> int | None:
        """Alias oficial do limite de anexos informado pelo Discord."""
        return self.limite_anexos

    @property
    def app_permissions(self) -> str | None:
        """Permissões efetivas da aplicação no canal resolvido, quando fornecidas pelo Discord."""
        return self.permissoes_aplicacao

    def _ler_opcoes_aninhadas(self, opcoes: list[dict[str, Any]], *, grupo: str | None = None) -> None:
        for opcao in opcoes:
            if not isinstance(opcao, dict) or "name" not in opcao:
                continue
            tipo = int(opcao.get("type", 0) or 0)
            nome = str(opcao["name"])
            if tipo == 2:
                self.grupo_subcomando = nome
                self._ler_opcoes_aninhadas(list(opcao.get("options", []) or []), grupo=nome)
            elif tipo == 1:
                self.subcomando = nome
                self._ler_opcoes_aninhadas(list(opcao.get("options", []) or []), grupo=grupo)
            elif "value" in opcao:
                self.opcoes[nome] = opcao["value"]

    async def responder(self, conteudo: str = "", *, embed: Embed | None = None, view: Any = None, ephemeral: bool = False, arquivos: Iterable[Any] | None = None, campos_multipart: dict[str, Any] | None = None) -> Any:
        corpo: dict[str, Any] = {"type": 4, "data": {"content": conteudo}}
        if embed: corpo["data"]["embeds"] = [embed.para_dict()]
        if view is not None: corpo["data"]["components"] = view.para_componentes()
        if ephemeral: corpo["data"]["flags"] = 64
        opcoes: dict[str, Any] = {"json": corpo}
        if arquivos is not None:
            opcoes["arquivos"] = arquivos
        if campos_multipart is not None:
            opcoes["campos_multipart"] = campos_multipart
        return await self.cliente.requisitar("POST", f"/interactions/{self.id}/{self.token}/callback", **opcoes)

    async def responder_autocomplete(self, escolhas: list[dict[str, Any]] | list[str]) -> Any:
        """Responde a uma interação de autocomplete com sugestões normalizadas."""
        normalizadas = [{"name": str(item), "value": str(item)} if not isinstance(item, dict) else item for item in escolhas[:25]]
        corpo = {"type": 8, "data": {"choices": normalizadas}}
        return await self.cliente.requisitar("POST", f"/interactions/{self.id}/{self.token}/callback", json=corpo)

    async def adiar(self, *, ephemeral: bool = False) -> Any:
        """Adia a resposta inicial para ganhar tempo de processamento."""
        corpo: dict[str, Any] = {"type": 5, "data": {}}
        if ephemeral: corpo["data"]["flags"] = 64
        return await self.cliente.requisitar("POST", f"/interactions/{self.id}/{self.token}/callback", json=corpo)

    def _rota_webhook(self) -> str:
        if not self.application_id:
            raise ErroDeConfiguracao("application_id é necessário para usar follow-ups de uma interação.")
        return f"/webhooks/{self.application_id}/{self.token}"

    async def followup(self, conteudo: str = "", *, embed: Embed | None = None, view: Any = None, ephemeral: bool = False, arquivos: Iterable[Any] | None = None, campos_multipart: dict[str, Any] | None = None) -> Any:
        corpo: dict[str, Any] = {"content": conteudo}
        if embed: corpo["embeds"] = [embed.para_dict()]
        if view is not None: corpo["components"] = view.para_componentes()
        if ephemeral: corpo["flags"] = 64
        opcoes: dict[str, Any] = {"json": corpo}
        if arquivos is not None:
            opcoes["arquivos"] = arquivos
        if campos_multipart is not None:
            opcoes["campos_multipart"] = campos_multipart
        return await self.cliente.requisitar("POST", self._rota_webhook(), **opcoes)

    async def obter_followup(self, mensagem_id: str) -> Any:
        """Obtém um follow-up pelo ID, sem confundi-lo com a resposta original."""
        return await self.cliente.requisitar("GET", f"{self._rota_webhook()}/messages/{mensagem_id}")

    async def apagar_followup(self, mensagem_id: str) -> Any:
        return await self.cliente.requisitar("DELETE", f"{self._rota_webhook()}/messages/{mensagem_id}")

    async def editar_followup(self, mensagem_id: str, conteudo: str | None = None, *, embed: Embed | None = None, view: Any = None) -> Any:
        corpo: dict[str, Any] = {}
        if conteudo is not None: corpo["content"] = conteudo
        if embed is not None: corpo["embeds"] = [embed.para_dict()]
        if view is not None: corpo["components"] = view.para_componentes()
        return await self.cliente.requisitar("PATCH", f"{self._rota_webhook()}/messages/{mensagem_id}", json=corpo)

    async def apagar_resposta(self) -> Any:
        return await self.cliente.requisitar("DELETE", f"{self._rota_webhook()}/messages/@original")

    async def editar_resposta(self, conteudo: str | None = None, *, embed: Embed | None = None, view: Any = None) -> Any:
        corpo: dict[str, Any] = {}
        if conteudo is not None: corpo["content"] = conteudo
        if embed is not None: corpo["embeds"] = [embed.para_dict()]
        if view is not None: corpo["components"] = view.para_componentes()
        return await self.cliente.requisitar("PATCH", f"{self._rota_webhook()}/messages/@original", json=corpo)

"""Memória local consultável da PimcordIA.

A memória não é um modelo geral e não finge conhecer tudo. Ela organiza o
conhecimento disponível no ambiente: API pública do Pimcord, padrões da
biblioteca padrão do Python e regras de projeto verificáveis. O resultado é
usado como contexto antes da geração neural ou determinística.
"""
from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass
from typing import Iterable


@dataclass(frozen=True, slots=True)
class TrechoConhecimento:
    titulo: str
    texto: str
    termos: tuple[str, ...]


_TOPICOS_PYTHON = (
    ("asyncio", "concorrência assíncrona, corrotinas, tarefas, cancelamento e asyncio.gather"),
    ("sqlite3", "persistência SQLite, conexão, transações, consultas parametrizadas e sqlite3.Row"),
    ("typing", "anotações, Protocol, TypeVar, Generic, Literal, TypedDict e tipos opcionais"),
    ("dataclasses", "modelos de dados imutáveis, slots, defaults e validação de estado"),
    ("pathlib", "caminhos portáveis, leitura, escrita e criação segura de diretórios"),
    ("logging", "logs estruturados, níveis, handlers e diagnóstico sem expor segredos"),
    ("ast", "parse, análise estática e validação de código Python sem execução"),
    ("json", "serialização, desserialização, schema e tratamento de JSON inválido"),
    ("re", "expressões regulares, grupos nomeados e normalização de texto"),
    ("datetime", "datas, fusos, timedelta e armazenamento consistente de horários"),
    ("contextlib", "gerenciadores de contexto síncronos e assíncronos"),
    ("collections", "defaultdict, Counter, deque e estruturas de dados"),
    ("enum", "enums para estados, permissões e valores controlados"),
    ("functools", "cache, wraps, partial e composição de funções"),
    ("inspect", "assinaturas, introspecção e identificação de corrotinas"),
    ("unittest", "fixtures, mocks, casos de teste e isolamento"),
)


def _normalizar(texto: str) -> str:
    return unicodedata.normalize("NFKD", texto.casefold()).encode("ascii", "ignore").decode()


def _palavras(texto: str) -> set[str]:
    return {item for item in re.findall(r"[a-z0-9_]{2,}", _normalizar(texto))}


def _trechos_python() -> tuple[TrechoConhecimento, ...]:
    return tuple(
        TrechoConhecimento(
            titulo=f"Python: {nome}",
            texto=f"{nome}: {descricao}. Prefira APIs documentadas, tratamento explícito de erros e testes isolados.",
            termos=(nome, *descricao.split()),
        )
        for nome, descricao in _TOPICOS_PYTHON
    )


def _trechos_pimcord() -> tuple[TrechoConhecimento, ...]:
    try:
        from .catalogo import catalogar
        modulos = catalogar().get("modulos", {}).get("pimcord", {})
    except Exception:
        modulos = {}
    saida: list[TrechoConhecimento] = []
    for nome, item in modulos.items():
        doc = str(item.get("doc", "")).strip()
        assinatura = str(item.get("assinatura", "")).strip()
        metodos = ", ".join(str(chave) for chave in item.get("metodos", {}))
        texto = f"{nome}{assinatura}. {doc} Métodos: {metodos}."
        saida.append(TrechoConhecimento(f"Pimcord: {nome}", texto, tuple(_palavras(texto))))
    return tuple(saida)


class MemoriaLocal:
    """Índice pequeno, determinístico e sem rede para recuperação de contexto."""

    def __init__(self, trechos: Iterable[TrechoConhecimento] | None = None) -> None:
        self.trechos = tuple(trechos) if trechos is not None else (*_trechos_python(), *_trechos_pimcord())

    def consultar(self, pedido: str, *, limite: int = 12) -> str:
        if not isinstance(pedido, str) or not pedido.strip():
            return ""
        consulta = _palavras(pedido)
        pontuados: list[tuple[int, TrechoConhecimento]] = []
        for trecho in self.trechos:
            termos = _palavras(" ".join(trecho.termos))
            pontos = len(consulta & termos)
            if pontos:
                pontuados.append((pontos, trecho))
        pontuados.sort(key=lambda item: (-item[0], item[1].titulo))
        selecionados = [trecho.texto for _, trecho in pontuados[:max(1, limite)]]
        return "\n".join(f"- {texto}" for texto in selecionados)


def contexto_local(pedido: str, *, limite: int = 12) -> str:
    """Retorna contexto de Python e Pimcord para anexar ao prompt."""
    return MemoriaLocal().consultar(pedido, limite=limite)


__all__ = ["TrechoConhecimento", "MemoriaLocal", "contexto_local"]

"""Inferência opcional da PimcordIA Neural com modelos armazenados localmente.

O módulo é deliberadamente opt-in: importar Pimcord não baixa pesos, não acessa
rede e não substitui o gerador determinístico até que o usuário forneça um
checkpoint local. Todo projeto retornado passa pelo contrato de ``projeto_ia``.
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable


@dataclass(frozen=True, slots=True)
class ConfiguracaoModelo:
    """Contrato de um modelo local especializado, sem download implícito."""

    familia: str = "qwen2.5-coder"
    contexto: int = 32768
    somente_local: bool = True
    nome_recomendado: str = "Qwen2.5-Coder-7B-Instruct"


CONFIGURACAO_RECOMENDADA = ConfiguracaoModelo()


class ErroModeloNeural(RuntimeError):
    """Checkpoint ausente, dependência não instalada ou saída inválida."""


class ModeloNeuralLocal:
    """Carrega um checkpoint causal local exclusivamente em modo offline."""

    def __init__(self, diretorio: str | Path, *, base: str | Path | None = None, dispositivo: str = "auto", configuracao: ConfiguracaoModelo = CONFIGURACAO_RECOMENDADA) -> None:
        self.diretorio = Path(diretorio).expanduser().resolve()
        self.configuracao = configuracao
        if not self.diretorio.is_dir():
            raise ErroModeloNeural(f"Checkpoint não encontrado: {self.diretorio}")
        self._proprio = (self.diretorio / "modelo.pt").is_file() and (self.diretorio / "tokenizador.json").is_file()
        if self._proprio:
            try:
                from .modelo_proprio import TokenizadorBytes, carregar_checkpoint
                self.tokenizador = TokenizadorBytes.carregar(self.diretorio / "tokenizador.json")
                self.modelo = carregar_checkpoint(self.diretorio, dispositivo="cpu" if dispositivo == "auto" else dispositivo)
            except Exception as erro:
                raise ErroModeloNeural(f"Falha ao carregar o checkpoint próprio da PimcordIA: {erro}") from erro
            self.dispositivo = "cpu" if dispositivo == "auto" else dispositivo
            return
        e_adaptador = (self.diretorio / "adapter_config.json").is_file()
        base_caminho = Path(base).expanduser().resolve() if base else None
        if e_adaptador and base_caminho is None:
            raise ErroModeloNeural(
                "Este diretório é um adaptador LoRA. Informe o modelo-base local com "
                "PIMCORDIA_MODELO_BASE ou ModeloNeuralLocal(..., base=...)."
            )
        origem_modelo = base_caminho or self.diretorio
        if not (origem_modelo / "config.json").is_file():
            raise ErroModeloNeural(f"Modelo-base sem config.json: {origem_modelo}")
        try:
            from transformers import AutoModelForCausalLM, AutoTokenizer
        except ImportError as erro:
            raise ErroModeloNeural(
                "Inferência neural exige transformers no ambiente de execução. "
                "No Pydroid, instale uma versão compatível ou use o fallback local."
            ) from erro
        kwargs: dict[str, Any] = {"local_files_only": self.configuracao.somente_local}
        tokenizer_origem = self.diretorio if (self.diretorio / "tokenizer_config.json").is_file() else origem_modelo
        self.tokenizador = AutoTokenizer.from_pretrained(str(tokenizer_origem), **kwargs)
        self.modelo = AutoModelForCausalLM.from_pretrained(str(origem_modelo), **kwargs)
        if e_adaptador:
            try:
                from peft import PeftModel
                self.modelo = PeftModel.from_pretrained(self.modelo, str(self.diretorio), **kwargs)
            except ImportError as erro:
                raise ErroModeloNeural("Este checkpoint LoRA exige a dependência peft.") from erro
            except Exception as erro:
                raise ErroModeloNeural(f"Falha ao carregar o adaptador LoRA: {erro}") from erro
        if dispositivo == "auto":
            dispositivo = "cuda" if self._tem_cuda() else "cpu"
        self.dispositivo = dispositivo
        self.modelo.to(dispositivo)
        self.modelo.eval()

    @staticmethod
    def _tem_cuda() -> bool:
        try:
            import torch
            return bool(torch.cuda.is_available())
        except ImportError:
            return False

    def gerar(self, prompt: str, *, max_novos_tokens: int = 2048, temperatura: float = 0.2) -> str:
        if not isinstance(prompt, str) or not prompt.strip():
            raise ErroModeloNeural("O prompt não pode ser vazio.")
        if self._proprio:
            try:
                from .modelo_proprio import gerar_texto
                return gerar_texto(self.modelo, prompt, dispositivo=self.dispositivo, novos_tokens=max_novos_tokens, temperatura=temperatura)
            except Exception as erro:
                raise ErroModeloNeural(f"Falha na inferência do modelo próprio: {erro}") from erro
        try:
            import torch
            if getattr(self.tokenizador, "chat_template", None):
                mensagens = [{"role": "system", "content": "Você é a PimcordIA, especialista em Python e na API Pimcord. Responda somente ao pedido técnico."}, {"role": "user", "content": prompt}]
                entradas = self.tokenizador.apply_chat_template(mensagens, add_generation_prompt=True, tokenize=True, return_tensors="pt")
                if hasattr(entradas, "items"):
                    entradas = {chave: valor.to(self.dispositivo) for chave, valor in entradas.items()}
                else:
                    entradas = {"input_ids": entradas.to(self.dispositivo)}
            else:
                entradas = self.tokenizador(prompt, return_tensors="pt")
                entradas = {chave: valor.to(self.dispositivo) for chave, valor in entradas.items()}
            with torch.no_grad():
                saida = self.modelo.generate(
                    **entradas,
                    max_new_tokens=max_novos_tokens,
                    do_sample=temperatura > 0,
                    temperature=max(0.05, temperatura) if temperatura > 0 else None,
                    pad_token_id=self.tokenizador.pad_token_id or self.tokenizador.eos_token_id,
                    eos_token_id=self.tokenizador.eos_token_id,
                )
            inicio = entradas["input_ids"].shape[-1]
            return self.tokenizador.decode(saida[0][inicio:], skip_special_tokens=True).strip()
        except Exception as erro:
            raise ErroModeloNeural(f"Falha na inferência local: {erro}") from erro

    def gerar_json(self, prompt: str, **opcoes: Any) -> dict[str, Any]:
        texto = self.gerar(prompt, **opcoes)
        candidato = texto.strip()
        if "```" in candidato:
            partes = [parte.strip() for parte in candidato.split("```") if parte.strip()]
            candidato = next((parte[4:].lstrip() if parte.startswith("json") else parte for parte in partes if "{" in parte), candidato)
        inicio, fim = candidato.find("{"), candidato.rfind("}")
        if inicio < 0 or fim <= inicio:
            raise ErroModeloNeural("O checkpoint não retornou um objeto JSON.")
        try:
            valor = json.loads(candidato[inicio:fim + 1])
        except json.JSONDecodeError as erro:
            raise ErroModeloNeural("A saída neural contém JSON inválido.") from erro
        if not isinstance(valor, dict):
            raise ErroModeloNeural("A saída neural precisa ser um objeto JSON.")
        return valor


class AgenteNeuralLocal:
    """Gera, valida e revisa projetos com limite explícito de iterações."""

    def __init__(self, modelo: ModeloNeuralLocal, *, max_iteracoes: int = 3, progresso: Callable[[str], Any] | None = None) -> None:
        if max_iteracoes < 1 or max_iteracoes > 8:
            raise ValueError("max_iteracoes deve estar entre 1 e 8.")
        self.modelo = modelo
        self.max_iteracoes = max_iteracoes
        self.progresso = progresso

    def _informar(self, texto: str) -> None:
        if self.progresso is not None:
            self.progresso(f"[PimcordIA Neural] {texto}")

    def construir(self, pedido: str) -> Any:
        if not isinstance(pedido, str) or not pedido.strip():
            raise ErroModeloNeural("O pedido não pode ser vazio.")
        from .ia import contexto_python_pimcord, resumo_api_pimcord, _validar_pedido_dados_sensiveis
        from .projeto_ia import ProjetoGerado, validar_projeto, _validar_acoes_reais
        _validar_pedido_dados_sensiveis(pedido)
        memoria = contexto_python_pimcord(pedido, limite=16)
        base = (
            "Você é um gerador local de projetos Pimcord. Retorne exclusivamente JSON com "
            "nome, resumo e arquivos; cada arquivo tem caminho e conteudo. Implemente livremente "
            "o comportamento solicitado e use a API instalada quando apropriado. Não inclua valores "
            "reais de CPF, documentos, senhas, cartões, tokens ou credenciais. O projeto não será "
            "executado automaticamente.\nAPI instalada:\n" + resumo_api_pimcord() + "\nMemória local relevante:\n" + memoria + "\nPedido:\n" + pedido[:20000]
        )
        feedback = ""
        ultimo_erro = ""
        for tentativa in range(1, self.max_iteracoes + 1):
            self._informar(f"tentativa {tentativa}/{self.max_iteracoes}")
            prompt = base + ("\nErros da tentativa anterior; corrija somente o necessário:\n" + feedback if feedback else "")
            try:
                plano = self.modelo.gerar_json(prompt, max_novos_tokens=4096)
                plano = validar_projeto(plano)
                _validar_acoes_reais(plano, pedido)
                return ProjetoGerado(plano)
            except Exception as erro:
                ultimo_erro = str(erro)
                feedback = ultimo_erro[:4000]
        raise ErroModeloNeural(f"O agente não produziu um projeto válido após {self.max_iteracoes} tentativas: {ultimo_erro}")

"""Primitivas centrais do Pimcord."""
from __future__ import annotations
from dataclasses import dataclass, field
from enum import IntFlag
from typing import Any, Awaitable, Callable, Optional
import os

class PimcordErro(Exception): pass
class ErroDeConfiguracao(PimcordErro): pass
class ErroDeConexao(PimcordErro): pass
class ErroDeAutenticacao(PimcordErro): pass
class ErroDePermissao(PimcordErro): pass
class ComandoNaoEncontrado(PimcordErro): pass
class ComandoInvalido(PimcordErro): pass
class InteracaoExpirada(PimcordErro): pass
class RateLimitado(PimcordErro):
    def __init__(self, mensagem: str = "Rate limitado", *, espera: float | None = None, global_: bool = False, rota: str | None = None):
        super().__init__(mensagem)
        self.mensagem = mensagem
        self.espera = espera
        self.global_ = global_
        self.rota = rota


class ErroDaAPI(PimcordErro):
    def __init__(self, mensagem: str = "Erro da API", *, status: int | None = None, codigo: int | str | None = None, erros: Any = None, rota: str | None = None, metodo: str | None = None):
        super().__init__(mensagem)
        self.mensagem = mensagem
        self.status = status
        self.codigo = codigo
        self.erros = erros
        self.rota = rota
        self.metodo = metodo


class ErroDoGateway(PimcordErro):
    def __init__(self, mensagem: str = "Erro do Gateway", *, codigo: int | None = None, reconectavel: bool = True):
        super().__init__(mensagem)
        self.mensagem = mensagem
        self.codigo = codigo
        self.reconectavel = reconectavel

class Permissoes(IntFlag):
    nenhum = 0; ver_canal = 1 << 10; enviar_mensagens = 1 << 11
    gerenciar_canal = 1 << 4; gerenciar_servidor = 1 << 5; administrador = 1 << 3
    gerenciar_mensagens = 1 << 13; banir_membros = 1 << 2; expulsar_membros = 1 << 1
    @classmethod
    def todas(cls) -> "Permissoes": return cls((1 << 53) - 1)

@dataclass(slots=True)
class Intents:
    servidores: bool = True; membros: bool = False; mensagens: bool = True
    conteudo_mensagens: bool = True
    @classmethod
    def todos(cls) -> "Intents":
        """Ativa todos os intents representados pela versão atual do Pimcord."""
        return cls(servidores=True, membros=True, mensagens=True, conteudo_mensagens=True)
    @classmethod
    def all(cls) -> "Intents":
        """Alias internacional de :meth:`todos`."""
        return cls.todos()
    def mascara(self) -> int:
        valor = 0
        if self.servidores: valor |= 1 << 0
        if self.membros: valor |= 1 << 1
        if self.mensagens: valor |= 1 << 9
        if self.conteudo_mensagens: valor |= 1 << 15
        return valor

@dataclass(slots=True)
class Configuracao:
    token: Optional[str] = None; prefixo: str = "!"; intents: Intents = field(default_factory=Intents)
    application_id: Optional[str] = None
    @classmethod
    def ambiente(cls, prefixo: str = "!") -> "Configuracao":
        return cls(token=os.getenv("DISCORD_TOKEN"), prefixo=prefixo, application_id=os.getenv("DISCORD_APPLICATION_ID"))
    def validar(self) -> None:
        if not self.token: raise ErroDeConfiguracao("Token ausente. Passe-o a iniciar() ou defina DISCORD_TOKEN.")
        if not self.prefixo: raise ErroDeConfiguracao("O prefixo não pode ser vazio.")

@dataclass(slots=True)
class Embed:
    titulo: Optional[str] = None; descricao: Optional[str] = None; url: Optional[str] = None
    cor: Optional[int] = None; campos: list[dict[str, Any]] = field(default_factory=list)
    rodape: Optional[dict[str, Any]] = None; autor: Optional[dict[str, Any]] = None
    thumbnail: Optional[dict[str, Any]] = None; imagem: Optional[dict[str, Any]] = None
    def adicionar_campo(self, nome: str, valor: str, inline: bool = False) -> "Embed":
        self.campos.append({"name": nome, "value": valor, "inline": inline}); return self
    def para_dict(self) -> dict[str, Any]:
        d = {k: v for k, v in (("title", self.titulo), ("description", self.descricao), ("url", self.url), ("color", self.cor)) if v is not None}
        if self.campos: d["fields"] = self.campos
        if self.rodape: d["footer"] = self.rodape
        if self.autor: d["author"] = self.autor
        if self.thumbnail: d["thumbnail"] = self.thumbnail
        if self.imagem: d["image"] = self.imagem
        return d

@dataclass(slots=True)
class Contexto:
    bot: Any; mensagem: Any = None; comando: Any = None; argumentos: tuple[Any, ...] = ()
    autor: Any = None; servidor: Any = None; canal: Any = None; interacao: Any = None
    @property
    def message(self) -> Any:
        """Alias compatível para acessar a mensagem que disparou o comando."""
        return self.mensagem

    @property
    def canal_atual(self) -> Any:
        """Canal associado ao comando, seja prefixado ou slash."""
        if self.canal is not None:
            return self.canal
        if self.mensagem is not None:
            return getattr(self.mensagem, "canal", None)
        return getattr(self.interacao, "canal", None) if self.interacao is not None else None

    @property
    def autor_id(self) -> str | None:
        """ID do autor normalizado para mensagens e interações."""
        valor = getattr(self.autor, "id", self.autor)
        return str(valor) if valor is not None else None

    async def responder(self, conteudo: str = "", *, embed: Embed | None = None, view: Any = None, ephemeral: bool = False) -> Any:
        if self.interacao: return await self.interacao.responder(conteudo, embed=embed, view=view, ephemeral=ephemeral)
        if self.mensagem and getattr(self.mensagem, "canal", None): return await self.mensagem.canal.enviar(conteudo, embed=embed, view=view)
        return None
    async def responder_embed(self, embed: Embed) -> Any: return await self.responder(embed=embed)
    async def enviar(self, *args: Any, **kwargs: Any) -> Any: return await self.responder(*args, **kwargs)

@dataclass(slots=True)
class Botao:
    texto: str
    estilo: str = "primario"
    custom_id: str | None = None
    desabilitado: bool = False
    url: str | None = None
    linha: int = 0
    callback: Any = field(default=None, repr=False, compare=False)

    def __post_init__(self) -> None:
        if not self.texto or len(self.texto) > 80:
            raise ValueError("texto do botão deve ter entre 1 e 80 caracteres")
        if self.custom_id is not None and len(self.custom_id) > 100:
            raise ValueError("custom_id do botão não pode exceder 100 caracteres")
        if self.estilo not in {"primario", "secundario", "sucesso", "perigo", "link"}:
            raise ValueError("estilo de botão inválido")
        if self.estilo == "link" and not self.url:
            raise ValueError("botão de link exige URL")
        if self.estilo != "link" and self.url:
            raise ValueError("somente botão de link pode ter URL")

    def para_dict(self) -> dict[str, Any]:
        estilos = {"primario": 1, "secundario": 2, "sucesso": 3, "perigo": 4, "link": 5}
        dados: dict[str, Any] = {"type": 2, "style": estilos.get(self.estilo, 1), "label": self.texto, "disabled": self.desabilitado}
        if self.url:
            dados["url"] = self.url
        else:
            dados["custom_id"] = self.custom_id or self.texto.lower().replace(" ", "_")
        return dados

