_IMPORTS_PROIBIDOS = {"subprocess", "ctypes", "pickle", "marshal"}
_CHAMADAS_PROIBIDAS = {"eval", "exec", "compile", "system", "popen", "__import__"}
_ATRIBUTOS_PROIBIDOS = {"system", "popen", "spawn", "execv", "execve", "remove", "unlink", "rmtree"}


def _validar_python(caminho: str, conteudo: str) -> None:
    try:
        arvore = ast.parse(conteudo, filename=caminho)
    except SyntaxError as erro:
        raise ErroProjetoIA(f"Python inválido em {caminho}: {erro}") from erro
    for no in ast.walk(arvore):
        if isinstance(no, ast.Import):
            if any(alias.name.split(".")[0] in _IMPORTS_PROIBIDOS for alias in no.names):
                raise ErroProjetoIA(f"Import proibido em {caminho}.")
        elif isinstance(no, ast.ImportFrom) and (no.module or "").split(".")[0] in _IMPORTS_PROIBIDOS:
            raise ErroProjetoIA(f"Import proibido em {caminho}.")
        elif isinstance(no, ast.Call):
            nome_chamada = no.func.id if isinstance(no.func, ast.Name) else (no.func.attr if isinstance(no.func, ast.Attribute) else "")
            if nome_chamada in _CHAMADAS_PROIBIDAS or (isinstance(no.func, ast.Attribute) and no.func.attr in _ATRIBUTOS_PROIBIDOS):
                raise ErroProjetoIA(f"Chamada proibida em {caminho}: {nome_chamada}")


def _validar_acoes_reais(projeto: dict[str, Any], pedido: str) -> None:
    """Mantém o ponto de extensão para revisores sem bloquear ações do prompt."""
    if not isinstance(pedido, str) or not pedido.strip():
        raise ErroProjetoIA("O pedido não pode ser vazio.")


def _validar_grafo_imports(projeto: dict[str, Any]) -> None:
    """Confere imports relativos e módulos locais sem executar arquivos gerados."""
    arquivos = {item["caminho"] for item in projeto["arquivos"]}
    python = {caminho for caminho in arquivos if caminho.endswith(".py")}
    modulos_locais = {
        caminho[:-3].replace("/", ".") if caminho.endswith(".py") else caminho.replace("/", ".")
        for caminho in python
    }
    modulos_locais.update(caminho[:-12].replace("/", ".") for caminho in python if caminho.endswith("/__init__.py"))

    def existe_modulo(modulo: str, atual: str) -> bool:
        partes = [parte for parte in modulo.split(".") if parte]
        base = Path(atual).parent
        destino = base.joinpath(*partes)
        return str(destino.with_suffix(".py")) in python or str(destino / "__init__.py") in python

    for item in projeto["arquivos"]:
        caminho = item["caminho"]
        if not caminho.endswith(".py"):
            continue
        arvore = ast.parse(item["conteudo"], filename=caminho)
        for no in ast.walk(arvore):
            if isinstance(no, ast.ImportFrom):
                if no.level:
                    modulo = "." * no.level + (no.module or "")
                    if no.level == 1 and no.module and existe_modulo(no.module, caminho):
                        continue
                    if no.level >= 1 and no.module and not existe_modulo(no.module, caminho):
                        raise ErroProjetoIA(f"Import local ausente em {caminho}: {modulo}")
                elif no.module:
                    raiz = no.module.split(".", 1)[0]
                    if raiz in {nome.split(".", 1)[0] for nome in modulos_locais} or raiz == "pimcord":
                        continue
                    if importlib.util.find_spec(raiz) is None:
                        raise ErroProjetoIA(f"Módulo importado não encontrado em {caminho}: {no.module}")
            elif isinstance(no, ast.Import):
                for alias in no.names:
                    raiz = alias.name.split(".", 1)[0]
                    if raiz in {nome.split(".", 1)[0] for nome in modulos_locais}:
                        continue
                    if importlib.util.find_spec(raiz) is None and raiz != "pimcord":
                        raise ErroProjetoIA(f"Módulo importado não encontrado em {caminho}: {alias.name}")


def validar_projeto(projeto: Any) -> dict[str, Any]:
    if not isinstance(projeto, dict) or set(projeto) != {"nome", "resumo", "arquivos"}:
        raise ErroProjetoIA("Projeto fora do schema permitido.")
    arquivos = projeto["arquivos"]
    if not isinstance(arquivos, list) or not arquivos or len(arquivos) > 30:
        raise ErroProjetoIA("O projeto precisa conter entre 1 e 30 arquivos.")
    vistos: set[str] = set()
    for arquivo in arquivos:
        if not isinstance(arquivo, dict) or set(arquivo) != {"caminho", "conteudo"}:
            raise ErroProjetoIA("Arquivo fora do schema permitido.")
        caminho = arquivo["caminho"]
        conteudo = arquivo["conteudo"]
        if not isinstance(caminho, str):
            raise ErroProjetoIA("Caminho de arquivo precisa ser texto.")
        normalizado = Path(caminho)
        if caminho.startswith(("/", "\\")) or ".." in normalizado.parts:
            raise ErroProjetoIA(f"Caminho inseguro: {caminho!r}")
        if not re.fullmatch(r"[A-Za-z0-9_./-]+", caminho) or caminho in vistos:
            raise ErroProjetoIA(f"Caminho inválido ou duplicado: {caminho!r}")
        if not isinstance(conteudo, str) or len(conteudo) > 100000:
            raise ErroProjetoIA(f"Conteúdo inválido: {caminho!r}")
        vistos.add(caminho)
        if caminho.endswith(".py"):
            _validar_python(caminho, conteudo)
        if caminho not in {".env.example", ".env.template"}:
            for correspondencia in re.finditer(r"(?i)(discord_token|token_do_bot|api_key)\s*=\s*[\"']?([^\s\"'`]+)", conteudo):
                valor = correspondencia.group(2).strip()
                if valor not in {"...", "placeholder", "seu_token", "cole_o_token_apenas_no_ambiente_local"}:
                    raise ErroProjetoIA(f"Possível segredo embutido em {caminho}.")
    return projeto


@dataclass(slots=True)
class ProjetoGerado:
    plano: dict[str, Any]

    @property
    def nome(self) -> str:
        return self.plano["nome"]

    def caminhos(self) -> tuple[str, ...]:
        return tuple(item["caminho"] for item in self.plano["arquivos"])

    def salvar(self, diretorio: str | os.PathLike[str], *, token: str | None = None) -> Path:
        raiz = Path(diretorio).expanduser().resolve()
        raiz.mkdir(parents=True, exist_ok=True)
        validar_projeto(self.plano)
        for item in self.plano["arquivos"]:
            destino = (raiz / item["caminho"]).resolve()
            if raiz not in destino.parents and destino != raiz:
                raise ErroProjetoIA("Tentativa de sair do diretório do projeto.")
            destino.parent.mkdir(parents=True, exist_ok=True)
            destino.write_text(item["conteudo"], encoding="utf-8")
        if token:
            token_limpo = "".join(caractere for caractere in str(token) if not caractere.isspace() and 32 <= ord(caractere) != 127)
            if not token_limpo:
                raise ErroProjetoIA("Token vazio; o projeto não foi iniciado.")
            (raiz / ".env").write_text(f"DISCORD_TOKEN={token_limpo}\n", encoding="utf-8")
            gitignore = raiz / ".gitignore"
            atual = gitignore.read_text(encoding="utf-8") if gitignore.exists() else ""
            if ".env" not in {linha.strip() for linha in atual.splitlines()}:
                gitignore.write_text((atual.rstrip() + "\n.env\n") if atual.strip() else ".env\n", encoding="utf-8")
        return raiz

    def executar(self, diretorio: str | os.PathLike[str], *, token: str | None = None) -> int:
        """Executa explicitamente o bot salvo; nunca é chamado por ``gerar``."""
        raiz = Path(diretorio).expanduser().resolve()
        validar_projeto(self.plano)
        arquivo = raiz / "bot.py"
        if not arquivo.is_file():
            raise ErroProjetoIA("O projeto precisa ter bot.py para ser executado.")
        ambiente = os.environ.copy()
        if token:
            ambiente["DISCORD_TOKEN"] = token
        return subprocess.call([sys.executable, str(arquivo)], cwd=raiz, env=ambiente)


class AgenteConstrutorPimcord:
    """Agente local de construção iterativa para projetos Pimcord.

    O agente expõe as etapas de trabalho, compõe o projeto, revisa todos os
    arquivos Python com ``ast`` e só então salva. Ele não executa código gerado
    automaticamente e não finge possuir conhecimento de um modelo neural geral.
    """

    ETAPAS = (
        "Entendendo o pedido",
        "Planejando a arquitetura Python",
        "Criando os arquivos do projeto",
        "Implementando comandos híbridos e cogs",
        "Revisando imports e sintaxe",
        "Validando segurança",
        "Projeto concluído",
    )

    def __init__(self, *, progresso: Callable[[str], Any] | None = None, modelo_neural: Any | None = None, max_iteracoes: int = 3):
        # Sem callback, a IA trabalha em silêncio para não poluir o terminal do bot.
        # O chamador pode passar `progresso=print` ou um logger quando quiser acompanhar etapas.
        self.progresso = progresso
        self.modelo_neural = modelo_neural
        if max_iteracoes < 1 or max_iteracoes > 8:
            raise ValueError("max_iteracoes deve estar entre 1 e 8.")
        self.max_iteracoes = max_iteracoes

    def _informar(self, etapa: str) -> None:
        if self.progresso is not None:
            self.progresso(f"[PimcordIA] {etapa}...")

    def construir(self, pedido: str, diretorio: str | os.PathLike[str] | None = None) -> ProjetoGerado:
        if not isinstance(pedido, str) or not pedido.strip():
            raise ErroProjetoIA("O pedido não pode ser vazio.")
        from .ia import PimcordIA
        self._informar(self.ETAPAS[0])
        inteligencia = PimcordIA()
        analise = inteligencia.analisar(pedido)

"""Construtor declarativo local e seguro para bots Pimcord.

A DSL deste módulo não executa Python, shell, imports ou expressões arbitrárias.
Ela apenas registra comandos híbridos com respostas literais e eventos permitidos.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from getpass import getpass
from pathlib import Path
from typing import Any

from .ia import PimcordIA


class ErroBotPronto(ValueError):
    """Descrição inválida ou capacidade não permitida na DSL."""


_EVENTOS_PERMITIDOS = {"pronto", "ao_ligar"}
_CHAVES_PERMITIDAS = {"prefixo", "intents", "comando", "resposta", "aliases", "evento", "mensagem"}


@dataclass(slots=True)
class DefinicaoComando:
    nome: str
    resposta: str = ""
    aliases: tuple[str, ...] = ()


@dataclass(slots=True)
class DefinicaoBot:
    prefixo: str = "!"
    intents: str = "basicos"
    comandos: list[DefinicaoComando] = field(default_factory=list)
    eventos: dict[str, str] = field(default_factory=dict)


def _linha_chave(linha: str) -> tuple[str, str]:
    if ":" not in linha:
        raise ErroBotPronto(f"Linha inválida; use 'Chave: valor': {linha!r}")
    chave, valor = linha.split(":", 1)
    chave = chave.strip().casefold()
    if chave not in _CHAVES_PERMITIDAS:
        raise ErroBotPronto(f"Chave não permitida na DSL: {chave}")
    return chave, valor.strip()


def interpretar(descricao: str) -> DefinicaoBot:
    """Interpreta a DSL declarativa sem avaliar código fornecido pelo usuário."""
    if not isinstance(descricao, str) or not descricao.strip():
        raise ErroBotPronto("A descrição do bot não pode ser vazia.")
    definicao = DefinicaoBot()
    comando_atual: DefinicaoComando | None = None
    for numero, bruta in enumerate(descricao.splitlines(), 1):
        linha = bruta.strip()
        if not linha or linha.startswith("#"):
            continue
        try:
            chave, valor = _linha_chave(linha)
        except ErroBotPronto as erro:
            raise ErroBotPronto(f"Linha {numero}: {erro}") from erro
        if chave == "prefixo":
            if not valor or len(valor) > 3 or any(c.isspace() for c in valor):
                raise ErroBotPronto("O prefixo deve ter de 1 a 3 caracteres sem espaços.")
            definicao.prefixo = valor
        elif chave == "intents":
            valor = valor.casefold()
            if valor not in {"basicos", "todos"}:
                raise ErroBotPronto("Intents permitidos: basicos ou todos.")
            definicao.intents = valor
        elif chave == "comando":
            nome = valor.casefold()
            if not nome or any(c.isspace() for c in nome) or len(nome) > 32:
                raise ErroBotPronto("O nome do comando deve ser uma palavra de até 32 caracteres.")
            comando_atual = DefinicaoComando(nome)
            definicao.comandos.append(comando_atual)
        elif chave == "resposta":
            if comando_atual is None:
                raise ErroBotPronto("Resposta precisa vir depois de Comando.")
            if len(valor) > 2000:
                raise ErroBotPronto("A resposta não pode exceder 2000 caracteres.")
            comando_atual.resposta = valor
        elif chave == "aliases":
            if comando_atual is None:
                raise ErroBotPronto("Aliases precisa vir depois de Comando.")
            aliases = tuple(a.strip().casefold() for a in valor.split(",") if a.strip())
            if any(any(c.isspace() for c in alias) or len(alias) > 32 for alias in aliases):
                raise ErroBotPronto("Cada alias deve ser uma palavra de até 32 caracteres.")
            comando_atual.aliases = aliases
        elif chave in {"evento", "mensagem"}:
            evento = valor.casefold() if chave == "evento" else "pronto"
            if evento not in _EVENTOS_PERMITIDOS:
                raise ErroBotPronto("Eventos permitidos nesta versão: pronto ou ao_ligar.")
            definicao.eventos[evento] = valor if chave == "mensagem" else ""
    if not definicao.comandos and not definicao.eventos:
        raise ErroBotPronto("A descrição precisa declarar pelo menos um comando ou evento.")
    return definicao


def _normalizar_token(token: str) -> str:
    """Remove espaços e controles inseridos por cópia no terminal/mobile."""
    if not isinstance(token, str):
        raise ErroBotPronto("O token do bot precisa ser texto.")
    normalizado = "".join(
        caractere for caractere in token
        if not caractere.isspace() and 32 <= ord(caractere) != 127
    )
    if not normalizado:
        raise ErroBotPronto("Token vazio; o bot não foi iniciado.")
    return normalizado


def _obter_token(token: str | None) -> str:
    if token is None or not str(token).strip():
        token = getpass("Token do bot (não será exibido): ")
    return _normalizar_token(str(token))


def _persistir_token(token: str, diretorio: str | None = None) -> Path:
    """Salva o token apenas no `.env` local e ignora esse arquivo no Git."""
    raiz = Path(diretorio or ".").expanduser().resolve()
    raiz.mkdir(parents=True, exist_ok=True)
    caminho_env = raiz / ".env"
    linhas = caminho_env.read_text(encoding="utf-8").splitlines() if caminho_env.exists() else []
    linhas = [linha for linha in linhas if not linha.lstrip().startswith(("DISCORD_TOKEN=", "PIMCORD_TOKEN="))]
    linhas.append(f"DISCORD_TOKEN={token}")
    temporario = caminho_env.with_suffix(".env.tmp")
    temporario.write_text("\n".join(linhas) + "\n", encoding="utf-8")
    temporario.replace(caminho_env)
    try:
        caminho_env.chmod(0o600)
    except OSError:
        pass
    caminho_gitignore = raiz / ".gitignore"
    existentes = caminho_gitignore.read_text(encoding="utf-8").splitlines() if caminho_gitignore.exists() else []
    if ".env" not in {linha.strip() for linha in existentes}:
        existentes.append(".env")
        caminho_gitignore.write_text("\n".join(existentes) + "\n", encoding="utf-8")
    return caminho_env


def construir_plano(plano: dict[str, Any], *, token: str | None = None) -> Any:
    """Cria um Bot a partir de um plano JSON já validado."""
    from .bot import Bot
    from . import Intents

    if not isinstance(plano, dict) or set(plano) != {"prefixo", "intents", "comandos"}:
        raise ErroBotPronto("Plano precisa conter somente prefixo, intents e comandos.")
    prefixo = plano["prefixo"]
    intents_nome = plano["intents"]
    if not isinstance(prefixo, str) or not 1 <= len(prefixo) <= 3 or any(c.isspace() for c in prefixo):
        raise ErroBotPronto("Prefixo inválido no plano.")
    if intents_nome not in {"basicos", "todos"}:
        raise ErroBotPronto("Intents inválidos no plano.")
    definicao = DefinicaoBot(prefixo=prefixo, intents=intents_nome)
    for item in plano["comandos"]:
        if not isinstance(item, dict) or set(item) != {"nome", "resposta", "aliases"}:
            raise ErroBotPronto("Comando fora do plano permitido.")
        definicao.comandos.append(DefinicaoComando(item["nome"], item["resposta"], tuple(item["aliases"])))
    return _construir_definicao(definicao, token=token)


def _construir_definicao(definicao: DefinicaoBot, *, token: str | None = None) -> Any:
    from .bot import Bot
    from . import Intents

    intents = Intents.todos() if definicao.intents == "todos" else Intents()
    bot = Bot(prefixo=definicao.prefixo, intents=intents)
    from . import Permissoes
    for comando in definicao.comandos:
        nome_normalizado = comando.nome.casefold().strip()
        if nome_normalizado in {"limpar", "clear", "purge"}:
            async def limpar_mensagens(ctx, quantidade: int = 10):
                canal = ctx.canal_atual
                if canal is None:
                    await ctx.responder("Este comando precisa ser usado em um canal de texto.")
                    return
                quantidade = max(1, min(100, int(quantidade)))
                apagadas = await canal.purge(limite=quantidade)
                total = len(apagadas) if apagadas is not None else quantidade
                await ctx.responder(f"Apaguei {total} mensagem(ns).")

            bot.comando_hibrido(
                comando.nome,
                descricao="Apaga de 1 a 100 mensagens deste canal",
                aliases=list(comando.aliases),
                permissoes=int(Permissoes.gerenciar_mensagens),
            )(limpar_mensagens)
            continue

        resposta = comando.resposta

        async def callback(ctx, _resposta=resposta):
            return await ctx.responder(_resposta)

        bot.comando_hibrido(comando.nome, aliases=list(comando.aliases))(callback)
    for evento, mensagem in definicao.eventos.items():
        async def callback_evento(_mensagem=mensagem):
            if _mensagem:
                bot.logger.info("%s", _mensagem)
        bot.evento(evento)(callback_evento)
    if token is not None:
        bot.configuracao.token = token.strip()
    return bot


def construir(descricao: str, *, token: str | None = None) -> Any:
    """Cria um :class:`pimcord.Bot` sem conectar e sem solicitar token."""
    definicao = interpretar(descricao)
    return _construir_definicao(definicao, token=token)


def construir_com_ia(descricao: str, gerador: Any, *, token: str | None = None) -> Any:
    """Gera e valida um plano com um provedor injetado e constrói o Bot."""
    plano = gerador.gerar_plano(descricao)
    return construir_plano(plano, token=token)

def _parece_dsl(descricao: str) -> bool:
    chaves = ("prefixo:", "comando:", "resposta:", "aliases:", "intents:", "evento:", "mensagem:")
    linhas = [linha.strip().casefold() for linha in descricao.splitlines() if linha.strip() and not linha.strip().startswith("#")]
    return bool(linhas) and all(linha.startswith(chaves) for linha in linhas)


def bot_pronto(descricao: str, *, token: str | None = None, iniciar: bool = True, gerador: Any = None, diretorio: str | None = None) -> Any:
    """Cria um bot a partir de linguagem natural usando a IA nativa do Pimcord.

    Uma descrição livre, como ``"crie um bot de economia completo"``, passa pela
    ``PimcordIA`` própria. Quando ``diretorio`` é informado, o agente mostra etapas
    de entendimento, arquitetura, implementação e revisão, criando os arquivos do
    projeto antes de retornar. O usuário não importa SDK de IA nem configura chave
    externa. A DSL antiga continua aceita para compatibilidade. Passe ``iniciar=False``
    para construir sem conectar.
    """
    if gerador is not None:
        bot = construir_com_ia(descricao, gerador, token=token)
    elif _parece_dsl(descricao):
        bot = construir(descricao, token=token)
    else:
        print("🧠 PimcordIA: analisando o pedido...", flush=True)
        ia = PimcordIA()
        plano = ia.gerar_plano(descricao)
        print(f"🧩 PimcordIA Neural: plano encontrado com {len(plano['comandos'])} comando(s).", flush=True)
        bot = construir_plano(plano, token=token)
        if diretorio is not None:
            print("🛠️ PimcordIA Neural: construindo arquivos específicos do seu prompt...", flush=True)
            projeto = ia.gerar_projeto(descricao)
            print("🔎 PimcordIA Neural: revisando sintaxe, AST, imports e estrutura do projeto...", flush=True)
            projeto.salvar(diretorio, token=token if token else None)
            bot.projeto_gerado = projeto
            print(f"✅ PimcordIA Neural: projeto revisado em {diretorio}.", flush=True)
    token_utilizado: str | None = None
    if iniciar:
        token_utilizado = _obter_token(token)
    elif token is not None and str(token).strip():
        token_utilizado = _normalizar_token(str(token))

"""Primitivas de segurança para evitar exposição acidental de credenciais."""
from __future__ import annotations

import logging
import re
from collections.abc import Iterable
from typing import Any


class FiltroSegredos(logging.Filter):
    """Redige valores sensíveis em mensagens e argumentos de um LogRecord."""

    def __init__(self, segredos: Iterable[str] = ()) -> None:
        super().__init__()
        self._segredos = tuple(sorted({segredo for segredo in segredos if len(segredo) >= 6}, key=len, reverse=True))

    def adicionar(self, *segredos: str) -> None:
        self._segredos = tuple(sorted({*self._segredos, *(s for s in segredos if len(s) >= 6)}, key=len, reverse=True))

    def redigir(self, valor: Any) -> str:
        texto = str(valor)
        for segredo in self._segredos:
            texto = texto.replace(segredo, "[REDACTED]")
        texto = re.sub(r"(?i)(token|authorization|senha|password)(\s*[:=]\s*)([^\s,;]+)", r"\1\2[REDACTED]", texto)
        return texto

    def filter(self, registro: logging.LogRecord) -> bool:
        if isinstance(registro.msg, str):
            registro.msg = self.redigir(registro.msg)
        if isinstance(registro.args, dict):
            registro.args = {
                chave: self.redigir(valor) if isinstance(valor, str) else valor
                for chave, valor in registro.args.items()
            }
        elif isinstance(registro.args, tuple):
            registro.args = tuple(
                self.redigir(valor) if isinstance(valor, str) else valor
                for valor in registro.args
            )
        if registro.exc_info:
            registro.exc_text = None
        return True


def token_redigido(token: str | None) -> str:
    """Retorna uma representação segura para diagnóstico, sem revelar o token."""
    if not token:
        return "[ausente]"
    if len(token) < 8:
        return "[REDACTED]"
    return f"{token[:3]}…{token[-3:]}"


__all__ = ["FiltroSegredos", "token_redigido"]

"""Supervisor resiliente de shards do Pimcord.

A API pública é em português e permanece assíncrona. O supervisor não presume
um serviço externo: a coordenação pode ser local ou implementada por um
adaptador de transporte injetado pelo aplicativo.
"""
from __future__ import annotations

import asyncio
import json
import os
import tempfile
import time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Awaitable, Callable

from .coordenacao import Lease, TransporteCoordenação


@dataclass(slots=True)
class ShardInfo:
    id: int
    total: int
    conectado: bool = False
    latencia: float | None = None
    estado: str = "parado"
    reinicios: int = 0
    ultimo_erro: str | None = None
    ultima_mudanca: float = field(default_factory=time.monotonic)
    tarefa: asyncio.Task[Any] | None = field(default=None, repr=False)

    def pertence(self, servidor_id: int | str) -> bool:
        return (int(servidor_id) >> 22) % self.total == self.id

    def marcar(self, estado: str, *, latencia: float | None = None, erro: Exception | None = None) -> None:
        self.estado = estado
        self.conectado = estado == "conectado"
        if latencia is not None:
            self.latencia = latencia
        if erro is not None:
            self.ultimo_erro = f"{type(erro).__name__}: {erro}"
        self.ultima_mudanca = time.monotonic()


@dataclass(slots=True)
class GerenciadorDeShards:
    total: int
    iniciar_shard: Callable[[ShardInfo], Awaitable[Any]] | None = None
    shards: dict[int, ShardInfo] = field(default_factory=dict)
    max_reinicios: int | None = None
    atraso_inicial: float = 1.0
    atraso_maximo: float = 60.0
    _parando: bool = field(default=False, init=False, repr=False)
    coordenador: TransporteCoordenação | None = None
    trabalhador: str = "pimcord-local"
    duração_lease: float = 30.0
    caminho_checkpoint: str | Path | None = None

    def __post_init__(self) -> None:
        if self.total < 1:
            raise ValueError("total de shards deve ser maior que zero")
        if self.atraso_inicial <= 0 or self.atraso_maximo < self.atraso_inicial:
            raise ValueError("atrasos de reinício inválidos")
        if self.duração_lease <= 0:
            raise ValueError("duração do lease deve ser positiva")
        self.shards = {i: ShardInfo(i, self.total) for i in range(self.total)}
        self._carregar_checkpoint()

    def _carregar_checkpoint(self) -> None:
        if self.caminho_checkpoint is None:
            return
        caminho = Path(self.caminho_checkpoint)
        try:
            dados = json.loads(caminho.read_text(encoding="utf-8"))
        except (FileNotFoundError, OSError, ValueError, TypeError):
            return
        if dados.get("total") != self.total:
            return
        for chave, estado in (dados.get("shards") or {}).items():
            try:
                shard = self.shards[int(chave)]
            except (KeyError, TypeError, ValueError):
                continue
            shard.reinicios = max(0, int(estado.get("reinicios", 0)))
            shard.latencia = estado.get("latencia")
            shard.ultimo_erro = estado.get("ultimo_erro")
            retomavel = bool(estado.get("conectado")) or estado.get("estado") in {"conectado", "encerrado"}
            shard.estado = "retomando" if retomavel else "parado"
            shard.conectado = False

    def _salvar_checkpoint(self) -> None:
        if self.caminho_checkpoint is None:
            return
        caminho = Path(self.caminho_checkpoint)
        caminho.parent.mkdir(parents=True, exist_ok=True)
        dados = {"total": self.total, "trabalhador": self.trabalhador, "shards": self.estado()}
        fd, temporario = tempfile.mkstemp(prefix=f".{caminho.name}.", dir=str(caminho.parent))
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as arquivo:
                json.dump(dados, arquivo, ensure_ascii=False, sort_keys=True)
                arquivo.flush()
                os.fsync(arquivo.fileno())
            os.replace(temporario, caminho)
        finally:
            try:
                os.unlink(temporario)
            except FileNotFoundError:
                pass

    def shard_de_servidor(self, servidor_id: int | str) -> ShardInfo:
        return self.shards[(int(servidor_id) >> 22) % self.total]

    @property
    def saudavel(self) -> bool:
        return bool(self.shards) and all(shard.conectado for shard in self.shards.values())

    def estado(self) -> dict[int, dict[str, Any]]:
        return {
            shard.id: {
                "estado": shard.estado,
                "conectado": shard.conectado,
                "latencia": shard.latencia,
                "reinicios": shard.reinicios,
                "ultimo_erro": shard.ultimo_erro,
            }
            for shard in self.shards.values()
        }

    async def _publicar_estado(self, shard: ShardInfo) -> None:
        self._salvar_checkpoint()
        if self.coordenador is not None:
            await self.coordenador.publicar(f"shard:{shard.id}", self.estado()[shard.id])

    async def _supervisionar(self, shard: ShardInfo) -> None:
        atraso = self.atraso_inicial
        while not self._parando and (self.max_reinicios is None or shard.reinicios <= self.max_reinicios):
            lease: Lease | None = None
            if self.coordenador is not None:
                lease = await self.coordenador.adquirir(
                    f"shard:{shard.id}", self.trabalhador, duração=self.duração_lease
                )
                if lease is None:
                    shard.marcar("aguardando_lease")
                    await self._publicar_estado(shard)
                    await asyncio.sleep(min(self.duração_lease / 3, self.atraso_maximo))
                    continue
            shard.marcar("conectando")
            await self._publicar_estado(shard)
            try:
                if self.iniciar_shard is None:
                    shard.marcar("conectado")
                    await self._publicar_estado(shard)
                    return
                resultado = await self.iniciar_shard(shard)
                if isinstance(resultado, (int, float)):
                    shard.marcar("conectado", latencia=float(resultado))
                else:
                    shard.marcar("conectado")
                await self._publicar_estado(shard)
                return
            except asyncio.CancelledError:
                shard.marcar("encerrado")
                await self._publicar_estado(shard)
                raise
            except Exception as erro:
                shard.reinicios += 1
                shard.marcar("reconectando", erro=erro)
                if self._parando or (self.max_reinicios is not None and shard.reinicios > self.max_reinicios):
                    shard.marcar("falhou", erro=erro)
                    await self._publicar_estado(shard)
                    return
                await self._publicar_estado(shard)
                await asyncio.sleep(atraso)
                atraso = min(atraso * 2, self.atraso_maximo)
            finally:
                if lease is not None and self.coordenador is not None:
                    await self.coordenador.liberar(lease)

    async def iniciar(self) -> None:
        self._parando = False
        for shard in self.shards.values():
            if shard.tarefa and not shard.tarefa.done():
                continue
            shard.tarefa = asyncio.create_task(self._supervisionar(shard), name=f"pimcord-shard-{shard.id}")

    async def aguardar_saude(self, tempo_limite: float | None = None) -> bool:
        inicio = time.monotonic()
        while not self.saudavel:
            if tempo_limite is not None and time.monotonic() - inicio >= tempo_limite:
                return False
            if self._parando:
                return False
            await asyncio.sleep(0.05)
        return True

    async def reiniciar(self, shard_id: int) -> None:
        shard = self.shards[shard_id]
        if shard.tarefa and not shard.tarefa.done():
            shard.tarefa.cancel()
            await asyncio.gather(shard.tarefa, return_exceptions=True)
        shard.tarefa = asyncio.create_task(self._supervisionar(shard), name=f"pimcord-shard-{shard.id}")

    async def parar(self) -> None:
        self._parando = True
        tarefas = [shard.tarefa for shard in self.shards.values() if shard.tarefa and not shard.tarefa.done()]
        for tarefa in tarefas:
            tarefa.cancel()
        if tarefas:
            await asyncio.gather(*tarefas, return_exceptions=True)
        for shard in self.shards.values():
            shard.marcar("encerrado")
            await self._publicar_estado(shard)


__all__ = ["ShardInfo", "GerenciadorDeShards"]

"""Tarefas, filas e agendamento resiliente do Pimcord."""
from __future__ import annotations

import asyncio
import inspect
import logging
import random
from dataclasses import dataclass
from typing import Any, Awaitable, Callable, Generic, TypeVar

T = TypeVar("T")


@dataclass(slots=True)
class PoliticaRetentativa:
    tentativas: int = 3
    atraso_inicial: float = 1.0
    fator: float = 2.0
    atraso_maximo: float = 60.0
    jitter: float = 0.1

    def atraso(self, tentativa: int) -> float:
        base = min(self.atraso_inicial * (self.fator ** max(0, tentativa - 1)), self.atraso_maximo)
        return max(0.0, base + random.uniform(-self.jitter, self.jitter) * base)


class TarefaAgendada:
    def __init__(self, funcao: Callable[[], Any], intervalo: float, *, nome: str | None = None, politica: PoliticaRetentativa | None = None):
        self.funcao = funcao
        self.intervalo = float(intervalo)
        self.nome = nome or getattr(funcao, "__name__", "tarefa")
        self.politica = politica or PoliticaRetentativa()
        self.tarefa: asyncio.Task[Any] | None = None
        self.ultima_excecao: Exception | None = None
        self.execucoes = 0
        self.falhas = 0
        self.logger = logging.getLogger("pimcord.tarefas")

    @property
    def ativa(self) -> bool:
        return self.tarefa is not None and not self.tarefa.done()

    def iniciar(self) -> "TarefaAgendada":
        if self.ativa:
            return self
        self.tarefa = asyncio.create_task(self._executar(), name=f"pimcord:{self.nome}")
        return self

    async def _chamar(self) -> Any:
        resultado = self.funcao()
        return await resultado if inspect.isawaitable(resultado) else resultado

    async def _executar(self) -> None:
        while True:
            sucesso = False
            for tentativa in range(1, self.politica.tentativas + 1):
                try:
                    await self._chamar()
                    self.execucoes += 1
                    self.ultima_excecao = None
                    sucesso = True
                    break
                except asyncio.CancelledError:
                    raise
                except Exception as erro:
                    self.falhas += 1
                    self.ultima_excecao = erro
                    self.logger.exception("Falha na tarefa %s (tentativa %s/%s)", self.nome, tentativa, self.politica.tentativas)
                    if tentativa < self.politica.tentativas:
                        await asyncio.sleep(self.politica.atraso(tentativa))
            await asyncio.sleep(self.intervalo if sucesso else self.politica.atraso(self.politica.tentativas))

    async def parar(self) -> None:
        if self.tarefa:
            self.tarefa.cancel()
            try:
                await self.tarefa
            except asyncio.CancelledError:
                pass
            self.tarefa = None


class Agendador:
    def __init__(self):
        self.tarefas: dict[str, TarefaAgendada] = {}

    def registrar(self, nome: str, funcao: Callable[[], Any], intervalo: float, *, politica: PoliticaRetentativa | None = None) -> TarefaAgendada:
        if nome in self.tarefas:
            raise ValueError(f"Já existe uma tarefa chamada '{nome}'")
        tarefa = TarefaAgendada(funcao, intervalo, nome=nome, politica=politica)
        self.tarefas[nome] = tarefa
        return tarefa

    def iniciar_todas(self) -> None:
        for tarefa in self.tarefas.values():
            tarefa.iniciar()

    async def parar_todas(self) -> None:
        await asyncio.gather(*(tarefa.parar() for tarefa in self.tarefas.values()))


class FilaAssincrona(Generic[T]):
    """Fila limitada com produtores, consumidores e encerramento explícito."""
    _SENTINELA = object()

    def __init__(self, limite: int = 100):
        self._fila: asyncio.Queue[Any] = asyncio.Queue(maxsize=limite)
        self.limite = limite
        self.processados = 0
        self.erros = 0
        self.encerrada = False

    async def colocar(self, item: T) -> None:
        if self.encerrada:
            raise RuntimeError("A fila já foi encerrada")
        await self._fila.put(item)

    async def consumir(self, funcao: Callable[[T], Any], *, consumidores: int = 1) -> list[asyncio.Task[Any]]:
        async def trabalhador() -> None:
            while True:
                item = await self._fila.get()
                try:
                    if item is self._SENTINELA:
                        return
                    resultado = funcao(item)
                    if inspect.isawaitable(resultado):
                        await resultado
                    self.processados += 1
                except asyncio.CancelledError:
                    raise
                except Exception:
                    self.erros += 1
                    logging.getLogger("pimcord.fila").exception("Erro ao processar item da fila")
                finally:
                    self._fila.task_done()
        return [asyncio.create_task(trabalhador(), name=f"pimcord:fila:{i}") for i in range(max(1, consumidores))]

    async def encerrar(self, consumidores: int = 1) -> None:
        self.encerrada = True
        for _ in range(max(1, consumidores)):
            await self._fila.put(self._SENTINELA)


__all__ = ["PoliticaRetentativa", "TarefaAgendada", "Agendador", "FilaAssincrona"]

"""Transporte e sessão de voz do Pimcord.

A camada é assíncrona, modular e testável sem rede. O codec e a criptografia são
injetáveis para permitir suporte opcional a Opus, AEAD e DAVE sem obrigar
FFmpeg ou dependências nativas em ambientes móveis.
"""
from __future__ import annotations

import asyncio
import json
import logging
